quests[27914] = { id = 27914, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blessing of the Green Dragonflight", description = "You have done well, {name}. Jammal'an may have escaped our grasp, but his retreat paves the way for me to enter the temple as I desire.\n\nStay where you are and do not move. I will hasten your return by pulling your spirit to me through the Emerald Dream.\n\nThis may cause slight drowsiness.", sourceObjective = "Speak with Lord Itharius atop the Temple of Atal'Hakkar.", completion = "You have performed a great service for me and my kind, {name}. Accept this as a symbol of my gratitude, and of your courage.", sourceObjectiveStatus = "unverified-source-field" }
quests[27915] = { id = 27915, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Heart of the Temple", description = "I must confess I have a more personal involvement in this affair. One of the first of the green dragons corrupted here was my brother, Eranikus.\n\nI thought Eranikus gone, lost forever to the darkest rifts of nightmare, but I have heard that his shade has emerged within the temple. I know not whether it is truly him, or an empty, mournful echo.\n\nIf you wish to help me further, return to the Hall of Masks and journey through the archway into the true sanctum of the temple. I will find you there.", sourceObjective = "Speak with Lord Itharius again inside the Temple of Atal'Hakkar.", completion = "I am pleased to see you once again, {name}. You are truly noble to assist me further.", sourceObjectiveStatus = "unverified-source-field" }
quests[27916] = { id = 27916, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruag's Report", description = "Here is Ruag's report, {name}. Let him know his scout is still here.\n\nDo not speak of Helgrum. I will not distract others with news of tragedy.\n\nI have to be strong. We all have to be strong.", sourceObjective = "Deliver the Splinterspear Report to Dispatch Commander Ruag in Stonard.", progress = "Yes?", completion = "<Ruag reads over the report.>\n\nI see.  Thank you for this information, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27917] = { id = 27917, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sniffing Them Out", description = "I could smell Godfrey and his companions a mile away from here. They did an exceedingly poor job covering their tracks in flight. It will be the mistake that puts the final nail in their coffins.\n\nOne of them is very close, and though the scent has changed slightly in undeath, I'm fairly certain it's Ashbury's. Go inside and tear him to pieces, we'll ensure the Forsaken do not intervene with our task.", sourceObjective = "Kill Baron Ashbury.", progress = "Kill Ashbury before I lose my patience. You wouldn't like me when I'm angry...", completion = "The scent of freshly spilled traitor blood fills my nostrils, and it is absolutely invigorating. However, my bloodlust will not be sated until Godfrey lies on the floor as a lifeless heap.\n\nHe thinks an army of mindless corpses can stop the wrath of the Bloodfang? We'll gnaw on their bones for years to come after our work is done!", sourceObjectiveStatus = "unverified-source-field" }
quests[27918] = { id = 27918, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Harborage", description = "Anchorite Avuun is one of our uncorrupted bretheren, what other races know as Draenei. He came to The Harborage to heal us, and try to find a cure. It is he who sent me here to collect these crystals.\n\nHe watches over a very sick friend now... and despite sending word to the Exodar itself, he has not found any aid so far. Could you bring these crystals to him, {name}? You may be the only one able to assist him.", sourceObjective = "Deliver the Draenethyst Crystals to Anchorite Avuun.\n\nProvided item:", completion = "Thank you, {class}. I am afraid it may be too late... but I refuse to give up, even if the Exodar itself does not hear my cries.", sourceObjectiveStatus = "unverified-source-field" }
quests[27919] = { id = 27919, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Onward to the Blasted Lands", description = "We appreciate your assistance here in this swamp, {name}.  I would like to inform you that I have received correspondence from Nethergarde Keep.\n\nEnohar Thunderbrew has requested help in investigating the shipwrecks of the Red Reaches, but we have had none willing to make the journey, and I could not leave the Harborage.\n\nNethergarde Keep sits in the Blasted Lands, south of the Swamp of Sorrows.  Do not journey too close to Stonard on your way.", sourceObjective = "Journey to the Blasted Lands and speak with Enohar Thunderbrew in Nethergarde Keep.", completion = "Ah, has Avuun sent ye? Good, good...", sourceObjectiveStatus = "unverified-source-field" }
quests[27920] = { id = 27920, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Armored to the Teeth", description = "We've hit an unexpected snag in our assault on the keep, {name}. It seems the servants that tended to Baron Silverlaine and Commander Springvale in life do so now in death as well, and Godfrey has placed them directly between us and him.\n\nNot to worry, we won't let them be anything more than a minor inconvenience. Eliminate Silverlaine and Springvale both and not only will their guards no longer have masters to direct them, it will place us that much closer to our final goal.", sourceObjective = "Kill Baron Silverlaine and Commander Springvale.", progress = "It is infuriating that we have to kill these ghost soldiers when they are completely outside the main objective, but it must be done. Godfrey is a cunning foe indeed.", completion = "We're nearly there, {name}. The time is now to charge further ahead and take out Walden!", sourceObjectiveStatus = "unverified-source-field" }
quests[27921] = { id = 27921, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fighting Tooth and Claw", description = "It appears that Lord Walden has finally taken notice to our presence and has heightened his defenses. It's worthless really... nothing will deter our pack.\n\nThe path ahead to him is rife with powerful Scourge minions, but I trust that you will be able to clear the path for the rest of us to follow in. Once we kill Walden, it should be a straight shot to his cowardly leader.", sourceObjective = "Kill Lord Walden.", progress = "We're behind you, {name}.", completion = "<Packleader Ivar Bloodfang grins, revealing his razor-sharp teeth.>\n\nIt won't be long now before the entire keep is ours, thanks to your valiant efforts.", sourceObjectiveStatus = "unverified-source-field" }
quests[27922] = { id = 27922, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Traitors!", description = "Please, stranger.  You must help me.\n\nI came here to investigate the arrival of a powerful ally to the Neferset, only to be betrayed by my closest allies and given up to the enemy.\n\nGo to the terrace above us to the east and find the information I failed to uncover.  You'll need to hide from the Neferset.  Perhaps you can hide behind one of the large plants on the platform to conceal your presence.\n\nDo this for me and I will help your friends find their way to safety.", sourceObjective = "Hide behind the Neferset Frond and Uncover the Neferset Secret.", progress = "What did you witness, {name}?", completion = "A djinn!  We must escape as soon as possible.\n\nThis unholy alliance of the Neferset with the minions of Deathwing does not bode well for us.", sourceObjectiveStatus = "unverified-source-field" }
quests[27923] = { id = 27923, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smoke in Their Eyes", description = "I'm not sure what knuckle-headed plan your friend is concocting, but we're going to need a distraction if we're to stand a chance of escaping.\n\nTake the torch from that brazier and go start some fires.\n\nPerhaps if we divert the Neferset scum's attention away for a few minutes, we'll have the opportunity we need.", sourceObjective = "Burn Stacks of Hay inside the Lost City of the Tol'vir in Uldum.", completion = "Yes.  I hear the Neferset calling each other to the east.  This might yet work.", sourceObjectiveStatus = "unverified-source-field" }
quests[27924] = { id = 27924, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Budd's Plan", description = "I've an idea!  Trust me, it's a good one this time!\n\nGet some of those shiny armor pieces the cat-people wear.\n\nThis plan cannot fail.  Trust me.", sourceObjective = "Obtain 6 pieces of Neferset Armor.", progress = "Did you get the pieces, {name}?", completion = "Excellent.  You'll see, this can't possibly go wrong!", sourceObjectiveStatus = "unverified-source-field" }
quests[27925] = { id = 27925, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Efficient Excavations", description = "This manual describes outlandish theories on how to efficiently manage large groups of workers as they engage in the manual labor of various types of excavation.\n\nIt becomes clear to you that the author of the book is the figure in charge of the over-aggressive pillagers here.\n\nPerhaps an introduction is in order.", sourceObjective = "Bring 'Efficient Excavations' to Belloc Brightblade in Schnottz's Landing.\n\nProvided item:", sourceObjectiveStatus = "unverified-source-field" }
quests[27926] = { id = 27926, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eastern Hospitality", description = "The commander is quite busy now, I'm afraid.\n\nThe demands of an operation such as this require much of his attention these days.\n\nWhile you wait to speak with him, why don't you mingle with some of our guests?\n\nWe have invited a variety of Azeroth's most illustrious figures to be present when we unlock the secrets of this region.\n\nI am confident that you will find them most captivating.", sourceObjective = "Belloc Brightblade wants you to mingle with the guests at Schnottz's Landing.", progress = "Well, hello again, {class}.", completion = "I trust that you had no troubles fitting in with our guests, hmm?", sourceObjectiveStatus = "unverified-source-field" }
quests[27927] = { id = 27927, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Down to the Scar", description = "The Badlands are home to some unusual people, many of whom have been here for quite a long time.\n\nFor example, there were three gentlemen who were staying here in town.  I forget their names... the dwarf was Theldurin, I think?  Anyhow, they headed south with a pack full of ale a couple of days ago, and haven't been heard from since.  I think they were headed to that big scar.\n\nWould you mind checking in on them?  I'd like to make sure that they're alright.", sourceObjective = "Find Theldurin the Lost at the Scar of the Worldbreaker in the Badlands.", completion = "They sent you to check up on us?  Pshh... I've been around this desert longer than any of those chumps.  We're just soaking in some of the scenery and telling stories about old times.\n\nYou like telling stories?", sourceObjectiveStatus = "unverified-source-field" }
quests[27928] = { id = 27928, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Favor for the Furrier", description = "The commander can be most generous to those who demonstrate their loyalty, and I know of something that you can do to curry favor with him.\n\nBefore building up his... ehh... workforce, he dealt in the furs of animals.\n\nHe is quite skilled in the art of leatherworking. The furrier can do wonders with even the most tattered pelts.\n\nThe dried oasis to the east is said to be home to a rare breed of coyote.\n\nTheir furs would make a very thoughtful gift.", sourceObjective = "Collect 5 Desert Coyote Pelts.", progress = "Were you successful in your hunt?", completion = "Oh, these are exquisite!\n\nThe commander will be able to make a winter uniform with these.", sourceObjectiveStatus = "unverified-source-field" }
quests[27929] = { id = 27929, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drag 'em Down", description = "A single Dragonmaw drake is worth a dozen Wildhammer gryphon-riders. Take them off of their lice-ridden birds and they're nothing.\n\nEven you can slay them easily, Horde-{class}.\n\nHunt gryphon riders flying over the river north of Bloodgulch. Take this hook and fling it at them as they fly by. Their momentum will hurl them from their mount, right to your feet. Finish them! Kill a few Thundermar gryphon riders and I'll believe your Horde is as mighty as you say.", sourceObjective = "Use the Barbed Fleshhook to dismount and kill 4 Thundermar Gryphon Riders.", completion = "You look a little battered. Those dwarves didn't give you any challenge, did they?\n\nStill, that was an impressive show.", sourceObjectiveStatus = "unverified-source-field" }
quests[27930] = { id = 27930, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Devastation", description = "The coast is clear.  If Rheastrasza or the egg were able to miraculously evade Deathwing's flames, they would probably need your assistance as soon as possible.", sourceObjective = "Search for Rheastrasza.", completion = "Heroes:\n\nIf you are reading this, then my suspicions were correct.  Deathwing has found us.  The egg is destroyed, as am I.\n\nThis was, actually, the plan from the beginning.  You see... the egg that Deathwing destroyed was not the egg he sought.\n\nIt was mine.", sourceObjectiveStatus = "unverified-source-field" }
quests[27931] = { id = 27931, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Quaking Fields", description = "Before you can help us here, you're going have to deal with Therazane, the Stone Mother's, forces to the south. The elementals and giants upon the Quaking Fields are being mustered.\n\nThey too are after the middle fragment of the World Pillar. They'll attack us amidst our war with the stone troggs and we'll be unable to repel them.\n\nI've sent the arch geomancer ahead. Get to Slate Quicksand and do as he asks.", sourceObjective = "Speak with Slate Quicksand at the Quaking Fields in Deepholm.", completion = "Good, {race}, you're here.\n\nWe'll have to act fast if we're to prevent Therazane's forces from attacking.", sourceObjectiveStatus = "unverified-source-field" }
quests[27932] = { id = 27932, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Axe of Earthly Sundering", description = "The emerald colossi are the greatest of the Stone Mother's creatures. They must be the first to be removed from the field.\n\nI brought Stonefather Oremantle's axe for just this task. Use it to sunder the giants.\n\nThat should bring them down to a more manageable size for you to finish off.", sourceObjective = "Slay 5 Sundered Emerald Colossi.", progress = "We need more of those giants destroyed, {name}.", completion = "Thank you, {name}. Without all of their giants, Therazane's forces will have a harder time taking Stonehearth.\n\nNow, if you please, hand back the axe. I'll keep it safe until you can rescue the Stonefather.", sourceObjectiveStatus = "unverified-source-field" }
quests[27933] = { id = 27933, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elemental Ore", description = "You're going to have to deal with the leader of Therazane's forces here. However, to get you to him quickly and safely, I'm going to need to perform a ritual.\n\nGo out into the field and collect elemental ore from the ragers. With enough of it, I should be able to make you one with the ground to get you where you need to go.", sourceObjective = "Collect 6 Elemental Ore.", progress = "Have you all that is required?", completion = "These should do. I'll just need a moment to prepare the ritual.", sourceObjectiveStatus = "unverified-source-field" }
quests[27934] = { id = 27934, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One With the Ground", description = "The leader of the Stone Mother's forces here is the great earth elemental lord, Avalanchion. Luckily for us, the Twilight's Hammer cultists have decided to invade his lair. They're seeking to bind his elementals to their will.\n\nWe will take advantage of the chaos. The earth ritual that I invoke will make you one with the ground. It will take you near to Avalanchion without alerting him to your presence.\n\nIt's up to you to finish him.", sourceObjective = "Complete the One With the Ground ritual.", sourceObjectiveStatus = "unverified-source-field" }
quests[27935] = { id = 27935, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bring Down the Avalanche", description = "Avalanchion stands before you. Slay him to keep Therazane's forces from attacking Stonehearth.", sourceObjective = "Slay Avalanchion.", completion = "You've done what few others could have. Defeating Avalanchion was no small feat.\n\nI'm impressed, {name}. Will you help us with our war against the stone troggs so that we can rescue the Stonefather?", sourceObjectiveStatus = "unverified-source-field" }
quests[27936] = { id = 27936, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bring Down the Avalanche", description = "You have to go back and slay Avalanchion to keep Therazane's forces from attacking Stonehearth!", sourceObjective = "Slay Avalanchion.", completion = "You've done what few others could have. Defeating Avalanchion was no small feat.\n\nI'm impressed, {name}. Will you help us with our war against the stone troggs so that we can rescue the Stonefather?", sourceObjectiveStatus = "unverified-source-field" }
quests[27937] = { id = 27937, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hero Returns", description = "The Stonefather is waiting for you back south at Stonehearth.\n\nMake yourself presentable. You've earned a hero's welcome!", sourceObjective = "Present yourself to Stonefather Oremantle at Stonehearth in Deepholm.", completion = "Our hero returns!\n\nYou have saved my people, {name}. You have earned that which you seek.", sourceObjectiveStatus = "unverified-source-field" }
quests[27938] = { id = 27938, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Middle Fragment", description = "I present you with the key to Stonehearth. With it you may unlock the vault to my home and recover the middle fragment of the World Pillar.\n\nKeep the fragment safe, {name}. Make certain to get it to the Temple of Earth in the middle of Deepholm as quickly as possible!\n\nKnow that you are always welcome here.", sourceObjective = "Recover the Middle Fragment of the World Pillar.", progress = "You've returned. Did you recover the middle fragment?", completion = "The Middle Fragment of the World Pillar!\n\nThank you, {name}. I can only imagine what you had to go through to get this to us. I'll see to it that it's placed within the center of the chamber.", sourceObjectiveStatus = "unverified-source-field" }
quests[27939] = { id = 27939, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Desert Fox", description = "Zhere is much to be done in zhis region, {race}.\n\nVe bozh haf a burning passion for zhe ancient technologies here, do ve not?\n\nPerhaps zhere is a vay for us to vork togezher?\n\nLet us put zhe misunderstandinks of zhe past behind us zhen, hmm?\n\nNow, zhere is an elusive animal in zhe region to zhe east zhat I have been huntink. Brink me zhis creature as a token of your sincerity, hmm?\n\nZhen maybe I let you in on my operation...", sourceObjective = "Schnottz wants you to bring him the Desert Fox.", progress = "Have you captured zhe Desert Fox, {class}?", completion = "You've done it!\n\nPerhaps I can trust you vizh more serious matters, hmm?", sourceObjectiveStatus = "unverified-source-field" }
quests[27940] = { id = 27940, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dirty Birds", description = "The sky above the Shriveled Oasis is littered with these nasty vultures.\n\nLike infectious rodents with wings, these creatures serve no great purpose and inflict untold misery.\n\nRid the skies of this nuisance and leave the region better than you found it.", sourceObjective = "You are to slay 8 Diseased Vultures.", sourceObjectiveStatus = "unverified-source-field" }
quests[27941] = { id = 27941, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fashionism", description = "We have a strict policy among our ranks, one that we take most seriously.\n\nOur troops are to dress in official uniform at all times. This helps with organization, friendly fire incidents are reduced, and it keeps the troops looking wonderful!\n\nWe call it, Fashionism.\n\nWe've been running low on uniforms lately. I must ask that you recover them from the troopers that have fallen in the line of duty.\n\nYou should find plenty of the poor fellows east of here, at the Ruins of Ammon.", sourceObjective = "Belloc Brightblade wants you to collect 10 Trooper Uniforms.", progress = "Were you able to recover the uniforms we need?", completion = "Most efficient work, {class}.\n\nYou should rise rapidly through the ranks.", sourceObjectiveStatus = "unverified-source-field" }
quests[27942] = { id = 27942, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Idolatry", description = "Zhere is somezhink I need handled, {race}.\n\nMy most trusted advisor has run afoul of an ancient curse. A hex zhat has transformed zhe man into a turkey, of all zhings!\n\nI haff studied for days to discover a remedy for his condition, and finally I am ready to conduct zhe ritual.\n\nI vill reqvire several idols from zhe nearby ruins. You are to brink zhem to me at vonce!\n\nDismissed!", sourceObjective = "Commander Schnottz wants you to collect 8 Well-preserved Idols.", progress = "Haff you brought me zhe idols, {race}?", completion = "Zhese look to be of sufficient quality.\n\nVizh zhese, ve are vone shtep closah to zhe cleansink ritual.", sourceObjectiveStatus = "unverified-source-field" }
quests[27943] = { id = 27943, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angered Spirits", description = "Doctor Venkman vas vone of my greatest researchers, until he had to be put out of my misery.\n\nHe did leave me vizh vone of his greatest accomplishments, zhough. Against zhe properly attuned supernatural adversary, zhis veapon vill siphon zhe target's essence.\n\nIt is of key importance in zhe ritual I vill be attemptink.\n\nVhere do you come in, you ask? Simple. You have zhe priviledge of collecting zhe material.\n\nZhe veapon is calibrated to vork on zhe Furious Specters in zhe temple to zhe east.", sourceObjective = "Commander Schnottz wants you to use the L.P.A.C. to collect 5 Furious Spectral Essences.", progress = "Vell, little man? Vere you successful?", completion = "Very goot!\n\nYou have earned yourself a place at zhe ritual.\n\nYou shall be among zhe first to velcome Gobbles back to his... original form.", sourceObjectiveStatus = "unverified-source-field" }
quests[27944] = { id = 27944, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thinning the Brood", description = "We have been trying to get a foothold in The Darkwood for weeks now but that forest is infested with spiders.  Do me a favor and see if you can thin them out enough for us to set up an attack.\n\nCareful out there, I have heard reports of Horde troops nearby earlier in the week.", sourceObjective = "Kill 12 Darkwood Lurkers in The Darkwood. The Darkwood forest is just west of here, across the bridge on the central island.", progress = "Any luck with those spiders?", completion = "Nice work on those spiders, {name}.  At this rate, we will be taking that forest in no time.", sourceObjectiveStatus = "unverified-source-field" }
quests[27945] = { id = 27945, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paint it Black", description = "The ground bleeds, {class}. They tear it open, as one would gouge flesh.\n\nThese cultists relish their secrecy but the very elementals they use for their misdeeds can betray them. Seek out Obsidian Stoneslaves northeast of here, among the ruined earth we have named the Black Breach.\n\nShatter their bodies and find for me a perfect heart of black diamond. I will look into this heart. And I will bare its soul.", sourceObjective = "Acquire a Black Diamond Heart.", progress = "The heart. A stone heart, of purest black. Have you found one?", completion = "<Mallia removes her eyepatch and holds the black diamond before her empty eye socket.>\n\nWhat have we, what have we - breaches, the breaches number three. Two heads, one wholly given to its master. I see the future. A hammer united. A mountain shattered. Oh - OH!\n\n<Mallia drops the diamond to the floor, covering her face with her hands.>", sourceObjectiveStatus = "unverified-source-field" }
quests[27947] = { id = 27947, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Vision of Twilight", description = "Cho'gall keeps track of his minions through powerful magical orbs: \"The Eyes of Twilight.\"\n\nIn Mount Hyjal, the Guardians of Hyjal managed to find and manipulate one to their own ends. We must do the same. I want one of those orbs, and I want to use it to peer into the very heart of Cho'gall's lair.\n\nSearch the Black Breach, across the river to the northeast, and find an Eye of Twilight. Do whatever you need to bring it back to me!", sourceObjective = "Locate an Eye of Twilight within the Black Breach.", completion = "<The Eye sits before you, humming ominously with dark energies.>\n\n<Without warning, the orb rotates, as if to look at you. You sense a malevolent presence, as though the orb is alive.>", sourceObjectiveStatus = "unverified-source-field" }
quests[27948] = { id = 27948, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Sticky Task", description = "Finding supplies on the island has been difficult, to say the least.\n\nFortunately, we have found a good supply of silk in The Darkwood, just west of here.  The bad part of this story is that the silk comes from the glands on Broodmother spiders.  I need you to gather 4 of these for me.\n\nThat should be just enough to finish up this last set of shirts.", sourceObjective = "Collect 4 Sticky Silk Glands from Darkwood Broodmother spiders in The Darkwood. The Darkwood forest is just west of here, across the bridge on the central island.", progress = "Were you able to gather the sticky silk glands?", completion = "These glands will do nicely.  We are grateful for your help, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27949] = { id = 27949, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Forgotten", description = "Many soldiers died on this island {name}.  It is only fair that we pay our respects to them in any way that we can.\n\nI need you to travel to Forgotten Hill, due west of here and release our brothers in arms' tortured souls away from this place.  Do be careful over there, reports of undead have been ongoing in the area.", sourceObjective = "Release the spirits of 6 tortured souls at Forgotten Hill. Souls can be channeled by touching your hands directly to the gravestones. Forgotten Hill is due west of here, past The Darkwood and The Restless Front.", completion = "May their souls rest in peace.", sourceObjectiveStatus = "unverified-source-field" }
quests[27950] = { id = 27950, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gobbles!", description = "At last! Zhe time has come to set my Gobbles free of zhat nasty curse!\n\nPay attention now, {race}, and stay on guard. Zhere can be no interruptions vhile I perform zhe ritual.\n\nLet me know vhen you haf secured zhe perimeter!\n\nNow, move it!", sourceObjective = "Schnottz wants you to speak with him when you are prepared to witness the ritual.", sourceObjectiveStatus = "unverified-source-field" }
quests[27951] = { id = 27951, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We All Must Sacrifice", description = "<The eye speaks to you, its 'voice' reverberating as if coming from everywhere at once.>\n\nYou seek my sight, {race}? My powers come at a price. These disciples of the Twilight have been honoring me with the blood of Wildhammer dwarves from the nearby ruins, but still I thirst. Perhaps you can do better.\n\nSlay my old masters, and my vision is yours. Honor me with the slaughter of the Shaman of the Black. Blood is blood, after all.", sourceObjective = "Slay 10 Shaman of the Black.", progress = "I have been watching you, {race}.", completion = "<The Eye glimmers darkly, colors swirling about its dusky surface.>\n\nAh, the succulent thrill of life extinguished. Do you feel it, {class}? Do you relish it as I do?\n\nNo, I see not. You fight to protect the lives of others. Pity.", sourceObjectiveStatus = "unverified-source-field" }
quests[27952] = { id = 27952, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Explorers", description = "We have a contingent of the Explorers' League in the chamber just to the northwest inside the temple.\n\nThey've been making increasing noises about something that the Twilight's Hammer is up to.\n\n{name}, would you be a dear and see what they need?", sourceObjective = "Speak with Explorer Mowi at the Temple of Earth in Deepholm.", completion = "Oh gosh! Someone's finally here to help us?", sourceObjectiveStatus = "unverified-source-field" }
quests[27953] = { id = 27953, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Reliquary", description = "We have a contingent of the Reliquary in the chamber just to the northeast inside the temple.\n\nThey've been making increasing noises about something that the Twilight's Hammer is up to.\n\n{name}, would you be a dear and see what they need?", sourceObjective = "Speak with Examiner Rowe at the Temple of Earth in Deepholm.", completion = "Ah, it's about time someone came to speak with us on matters most urgent.", sourceObjectiveStatus = "unverified-source-field" }
quests[27954] = { id = 27954, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eyes Have It", description = "Very well then, {race}. You have purchased my services in blood. Take me back to Garona Halforcen.\n\nOh yes, I already know where you're taking me. Garona's relentless quest for vengeance is no secret. It will be a delight to watch it unfold.", sourceObjective = "Take the Eye of Twilight to Garona Halforcen at Bloodgulch in Twilight Highlands.", progress = "Did you have any luck within the Black Breach?", completion = "You found one? I've been searching everywhere. Give it here!\n\nSome of these eyes are won over with riddles or verse. Others require magic. What did this one demand? Ah, it's no matter. What matters is that it's ours.", sourceObjectiveStatus = "unverified-source-field" }
quests[27955] = { id = 27955, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eye Spy", description = "This terrible thing makes my hair stand on end. Cho'gall uses these to control his minions - now it's time to use it against him.\n\nLet me see... hmm, it's all cloudy. All I can see is you. Why is it showing me you?\n\n<Garona sets the eye out in front of her.>\n\nLook into the eye and tell me what you see. Peer into Cho'gall's lair! What is he doing? Is he heavily guarded? Tell me!", sourceObjective = "Peer into the Eye of Twilight for Garona.", progress = "What did the Eye show you?", completion = "You've gone pale, {class}. What did the Eye show you?\n\nYou saw Cho'gall? Wait - Cho'gall saw you? He's watching us? He's watching us right now!?\n\nDamn this stupid dark magic! I'm going to have to infiltrate Cho'gall's stronghold myself.", sourceObjectiveStatus = "unverified-source-field" }
quests[27956] = { id = 27956, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lunk's Task", description = "Lunk came from the Badlands.  Other ogres try to make Lunk fight.\n\nLunk hate fighting.  Lunk want to learn.\n\nLunk sees machines to the south.  Machines made of gears.\n\nMaybe if you ask nicely, machines will give you some gears?  Then maybe Lunk can have a gear, and learn about machines too.", sourceObjective = "Obtain 15 Tempered Flywheels from Tempered War Golems.", progress = "You get gears?  How you get them?", completion = "You didn't... KILL the machines to get these, right?.\n\n<Lunk looks upset.>\n\nRight?", sourceObjectiveStatus = "unverified-source-field" }
quests[27957] = { id = 27957, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lunk No Kill", sourceObjective = "No!  You are the same as Thorium Brotherhood dwarf.\n\n\"Kill dwarf.  Kill spider.  Kill machine.  Kill, kill, kill.\"\n\nLunk come to gorge to go on adventure, not to go on murder spree.\n\nGoodbye, {race}.  You kill too much.", sourceObjectiveStatus = "unverified-source-field" }
quests[27958] = { id = 27958, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Proper Antivenom", description = "Shame that Lunk left.  I was beginning to enjoy his company.\n\nOh well, back to work!\n\nI'm the closest thing that this expedition has to a medical officer, and I'm running low on antivenom.  We tend to need a lot of antivenom.\n\nThe key to a proper antivenom is ALWAYS to start with the poison itself.  The glassweb spiders nearby should be a good place to start.  If you kill them, you can probably extract some venom from the sacs within their jaws.", sourceObjective = "Obtain 14 samples of Glassweb Venom.", progress = "Well well, you certainly operate quickly!  You do have the venom, right?", completion = "This... this is way more than I expected.  This will last us for months!", sourceObjectiveStatus = "unverified-source-field" }
quests[27959] = { id = 27959, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lunk's Adventure: Spider Rider", description = "Lunk sees you like to kill things.  Let Lunk teach you another way.\n\nLunk always wanted to ride on spider's back.  Looks like fun.  Spiders move too fast, though.  Always slip away.\n\nWe work together.  You fight spider until it gets weak and tired.  Then Lunk jump on spider's back and ride around.\n\nMaybe Lunk even gather some venom for you!  No have to kill!", sourceObjective = "Weaken 7 Glassweb Spiders so Lunk can ride them.", sourceObjectiveStatus = "unverified-source-field" }
quests[27960] = { id = 27960, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fewer, the Better", description = "I'm not much of a fighter... I'm more of a mining dwarf.  Same goes for Jack and Pris.  And Lunk... well, you'd think he'd be a big fighter, but he's the biggest wimp of all of us.\n\nWhat I'm saying is, it's good that you came here when you did.\n\nIt seems likely that we in the Thorium Brotherhood are going to be fighting the other Dark Iron dwarves soon.  I'm thinking we should pick off some of their finest before the war starts in earnest.  Start with the geologists and watchmen to the south.", sourceObjective = "Slay 10 Dark Iron Geologists or Dark Iron Watchmen.", completion = "Thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[27961] = { id = 27961, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Out of Place", description = "The gorge is an unforgiving place.  We don't get a whole lot of fuzzy wildlife wandering around here.\n\nWe tried bringing in some wild game, but they haven't fared well at all.  There's just no food for them to eat.  Now the nearby spiders - which were already dangerous - are getting big and fat on chicken meat.\n\nWe'll never get rid of all the spiders, but we can salvage what few chickens remain.  Not only will you be feeding the Brotherhood, you'll be saving them a painful death by spider bite.", sourceObjective = "Obtain 8 Ash Chickens.", progress = "Those poor animals.", completion = "You've got quick hands if you were able to gather this many in such a short time.\n\nExcellent work, {name}.  I'll make sure these ones don't go to waste.", sourceObjectiveStatus = "unverified-source-field" }
quests[27962] = { id = 27962, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lumbering Relic", description = "Margol the Rager's an old thunder lizard seen round these parts.  Legend has it that he's been here in the gorge since before it was even a gorge.  Legend also has it that he ate my brother Barnabas.\n\nI don't care how old he is or what kind of magic he shoots out of his nose.  I just want him dead.  For Barnabas' sake.\n\nYou'll find him wandering the cliffs to the south of here.", sourceObjective = "Obtain Margol's Gigantic Horn.", progress = "Bring me the horn, {name}.", completion = "Yup, this was Margol's horn alright.  No doubt about it.\n\nBarnabas was a digger, like me.  He never stood a chance in combat against the beast.  I'm glad you were here to set things right.", sourceObjectiveStatus = "unverified-source-field" }
quests[27963] = { id = 27963, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Master... But Who?", description = "You've arrived just in time.\n\nHere's the skinny: the Dark Iron dwarves in the gorge have been acting strangely, and the Thorium Brotherhood intends to find out why.  Overseer Oilfist doesn't like surprises.\n\nWe suspect that they're following orders from some new leader.  I have reason to believe that Gravius Grimesilt, just south of here, knows who it is.\n\nEven here in Searing Gorge, we've begun to hear tales of your exploits, {name}.  You should have no problem with Grimesilt.", sourceObjective = "Obtain the Dark Iron Memo from Gravius Grimesilt at Grimesilt Worksite.", progress = "Any news?", completion = "Let's see... Overseer Maltorius... we're quite familiar with him and his work.\n\nWhat's this?  The \"archduke\"?  That sounds promising.", sourceObjectiveStatus = "unverified-source-field" }
quests[27964] = { id = 27964, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dig-Boss Dinwhisker", description = "Grimesilt wasn't as high up on the chain as I thought.  We'll have to take out his superior and find out what he knows.\n\nDig-Boss Dinwhisker's his name, and he runs the Dark Iron digging operations within the Cauldron, just northwest of here.  His excavators and footmen patrol the eastern side of the Cauldron, digging downward, day and night.\n\nHe's not known to show his face out in the field very often, but if you slay enough of his men, he'll be forced to come out and deal with you.", sourceObjective = "Kill Dark Iron Excavators and Dark Iron Footmen within the Cauldron until Dig-Boss Dinwhisker appears. Then slay Dig-Boss Dinwhisker and obtain his Dark Ember.", progress = "If Dinwhisker doesn't have what we seek, I'm not sure what we'll do next.", completion = "A... an ember?  What is this thing?", sourceObjectiveStatus = "unverified-source-field" }
quests[27965] = { id = 27965, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thorium Point: The Seat of the Brotherhood", description = "Did... did you see that?  This is the missing piece we've been looking for!  We have to take this information back to someone at Thorium Point.\n\nThe Dark Irons have been known to consort with the firelord in the past, but never before have they brought their kind this far out into Searing Gorge.\n\nThorium Point is west and north of here.  You will find it nestled in the cliffs that overlook Pyrox Flats.  Take this information straight to Overseer Oilfist.", sourceObjective = "Report to Overseer Oilfist at Thorium Point in Searing Gorge.", completion = "Do I know you, {race}?\n\n\n\nSounds like another one of Ragnaros' minions.  I don't like the sound of that.", sourceObjectiveStatus = "unverified-source-field" }
quests[27966] = { id = 27966, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salvaging the Remains", description = "Forgotten Hill has been overrun with zombies and ghouls ever since we reclaimed this wretched isle.  We have tried to clear them out many times but they always seem to come back.\n\nOne of our lieutenants recommended taking the ghouls' bones when we kill them in hopes that they can't reincarnate overnight.  Think you can help us out with this one?", sourceObjective = "You need to recover 9 Cursed Femur bones from the ghouls that inhabit Forgotten Hill. Forgotten Hill is on the west side of the island, just past The Forgotten Front.", progress = "Were you able to recover the femur bones?  Better for you to try than me.", completion = "I didn't think you would be able to do it, {name}.  You are just full of surprises aren't you?", sourceObjectiveStatus = "unverified-source-field" }
quests[27967] = { id = 27967, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "First Lieutenant Connor", description = "The first time I heard about Lt. Connor, I was just a young recruit in the Stormwind stockades.  None of us could believe he ended up here on Tol Barad.  Sadly, he still roams these wretched islands, wreaking havoc on our troops morale.\n\nI need you to put an end to his misery... and ours.", sourceObjective = "Find and kill First Lieutenant Connor at Forgotten Hill. You will find Forgotten Hill on the far west side of the island.", completion = "Hey, you made it back alive!  Can't say you were the first one to try this task, but you are definitely the first one to make it back alive.", sourceObjectiveStatus = "unverified-source-field" }
quests[27968] = { id = 27968, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fury of the Pack", description = "Ah, the sweet scent of victory! My men should be tearing Godfrey to pieces even as we speak. Go up to his domain and collect your share of the spoils - you've earned it!\n\nYou'd think that he would have been more difficult to defeat...", sourceObjective = "Kill Lord Godfrey.", progress = "Let's get going.", completion = "We did it, {name}! At terrible cost... but victory is ours.\n\nThis keep could serve well as a home for me and my pack, though we tend to prefer more natural habitats.\n\nIt may be best to leave it as a reminder of Godfrey's betrayal and of the Bloodfang warriors that died here in battle.", sourceObjectiveStatus = "unverified-source-field" }
quests[27969] = { id = 27969, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Make Yourself Useful", description = "Gobbles vill be sorely missed, but zhe mission must not suffer.\n\nPerhaps zhere is somezhink you can do to redeem yourself.\n\nTake vone of zhe uniforms you recovered. Vhile vearink it, my vorkers vill not behave so... aggressively.\n\nLately, zheir morale has been a bit lackink. Some of zhe vorkers are refusing to perform zheir labors.\n\nAuch, zhe audacity!\n\nFind zhese lazy imbeciles and convince zhem zhat zhey must get to vork... or else!", sourceObjective = "Commander Schnottz wants you to persuade 6 Slacking Laborers to get to work.", progress = "Vhell, {race}? Vere you... persvasive?", completion = "Vell done, {class}.\n\nZhere may be hope for you yet.", sourceObjectiveStatus = "unverified-source-field" }
quests[27970] = { id = 27970, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Captain P. Harris", description = "The Cape of Lost Hope has been a sore in our side for weeks here on Tol Barad.  Half of our supply ships end up on the rocks down there.\n\nTo make matters worse, it's been overrun by a gang of undead sailors.  We have tried thinning the ranks, but they just seem to keep coming back.  Our last resort is to try and take out the captain that they report to.  You should be able to find him on a ship, just off the shoreline.\n\nOh, and I hope you are not too scared of sharks.", sourceObjective = "You have been tasked with killing Captain P. Harris at the Cape of Lost Hope. The Cape of Lost Hope can be found northwest of here, along the coast. Just look for the shipwrecks.", completion = "You did it!  Maybe we can finally get some ships into port now.  Thank you {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27971] = { id = 27971, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rattling Their Cages", description = "We have been having issues with the undead down at the Cape of Lost Hope for a while now.  Every time a new ship wrecks, they end up getting more undead to join their ranks.\n\nCan you do us a favor and thin out the ranks up there?  I know you won't be able to kill them all, but anything you can do will help at this point.\n\nKeep an eye out for horde, we have been getting reports of them ambushing the beach lately.", sourceObjective = "Camp Coordinator Brack has asked you to kill 8 Shipwrecked Sailors at the Cape of Lost Hope. The cape is located due northwest of here, on the beach.", completion = "Nice work on the undead up there {name}.  We really appreciate the help.", sourceObjectiveStatus = "unverified-source-field" }
quests[27972] = { id = 27972, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boosting Morale", description = "Morale is low these days, {name}.  We make every effort we can to keep the troops in high spirits but we are running low on our main supply of morale booster... rum.\n\nI have been getting reports from our infantry to the south that the shipwrecks on the Cape of Lost Hope still have a good supply of southsea rum in their wrecked hulls.  Can you head up there and investigate?\n\nBring back any rum you can find.", sourceObjective = "You have been asked to recover 6 Barrels of Southsea Rum from the shipwrecks on the Cape of Lost Hope. The cape can be found north of here, along the coast.", progress = "Were you able to recover the rum?  I would try but I am deathly afraid of the water.  Not to mention that crazy shark.", completion = "This rum will really help us out, {name}.  They might not feel great in the morning but at least they will go to sleep happy.", sourceObjectiveStatus = "unverified-source-field" }
quests[27973] = { id = 27973, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Watch Out For Splinters!", description = "Have you been over to the Wellson Shipyard yet, {name}?  Best to stay away from there unless you have a good reason to venture in.  Unfortunately, that is exactly what I need you to do.\n\nYou see, we have been short on supplies ever since we recaptured the island.  That ghost ridden shipyard is overflowing with lumber but every time we send an escort to recover the lumber, they never make it back.\n\nCan you help us out?", sourceObjective = "Sergeant Gray has asked you to recover 15 pieces of Shipyard Lumber from the Wellson Shipyard. The lumber can be recovered from the ghosts in the shipyard or found lying around the premises. The shipyard can be found northwest of here, on the coast.", progress = "Did the ghosts scare you off?", completion = "I didn't think you would be able to do it, {name}.  You are just full of surprises aren't you?", sourceObjectiveStatus = "unverified-source-field" }
quests[27974] = { id = 27974, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This Land is Our Land", description = "Did you think that a handful of worgen vermin could stop me? Hah!\n\nShadowfang Keep was part of the Lordaeron kingdom in life, so it is quite fitting that it should belong to the Forsaken in death. Godfrey and his accomplices are minor obstacles at best, and of course we're all happy to take them out for their treachery against the Dark Lady.\n\nAshbury has positioned himself near the front of the keep, leaving him wide open to attack. Start us out on the right foot, would you?", sourceObjective = "Kill Baron Ashbury.", progress = "Don't test my patience and good will.", completion = "Ah, very well done! They've gotten a hold of powerful allies, but clearly nothing a {class}-champion of the Banshee Queen can't handle!", sourceObjectiveStatus = "unverified-source-field" }
quests[27975] = { id = 27975, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Foreman Wellson", description = "Foreman Wellson has been a pain in our side since we got here.  His shipyard holds a large amount of supplies that would be extremely useful to us... if we could get to them.\n\nHe keeps a close watch over his minions and makes it very difficult for us to get a foothold on the shipyard.  I need you to take out Wellson for good this time.  Be careful {name}, we have been receiving reports of filthy Horde all around the area.", sourceObjective = "Kill Foreman Wellson at the Wellson Shipyard. The shipyard can be found northwest of here, on the western coast.", progress = "Were you able to \"take care of\" Foreman Wellson?", completion = "Great work {name}.  I will report your efforts to our highest in command immediately.", sourceObjectiveStatus = "unverified-source-field" }
quests[27976] = { id = 27976, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Curse These Fat Fingers", description = "Unfortunately, I can't dish out the beats like I used to, due to this here fat finger problem.  Ye see, the climate out here combined with the lack o' air pressure makes me fingers expand.  They're like gigantic Thelsamar Blood Sausages, they are...\n\nYe're gonna have to carry out me orders of business and what have ye.\n\nFirst on me agenda: Poundin' the livin' daylights out o' the heavy war golems o' the Gorge.  Get crackin'.", sourceObjective = "Kill 12 Heavy War Golems.", completion = "Ye're a good lad, ye are. I got ye a lil' present fer yer troubles.", sourceObjectiveStatus = "unverified-source-field" }
quests[27977] = { id = 27977, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recon Essentials", description = "We used to have more stuff around here.  I think there was a spyglass somewhere nearby, along with a smithing tuyere.\n\nI'm pretty certain that they've been stolen by Dark Iron dwarves.  Yes, I know that I'm a Dark Iron dwarf!  I'm talking about the bad ones that live down in that gorge.\n\nYou'd best check the steamsmiths that work just south of here.  They'd be most likely to use tools like these.", sourceObjective = "Find and return the Smithing Tuyere and Lookout's Spyglass.", progress = "If you're here for the reward, you're gonna have to give me the stolen goods.", completion = "Fantastic work!", sourceObjectiveStatus = "unverified-source-field" }
quests[27978] = { id = 27978, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ghostbuster", description = "See that hill just beyond our base camp?  That's Largo's Overlook and it's not a fun place to setup camp next to.  We have been dealing with those spirits and spectres ever since we setup base camp.\n\nCan you head up there and let them know we don't plan on leaving anytime soon?  A few good kills on their ranks should put them in line.\n\nThanks for your help on this, {name}.", sourceObjective = "Kill 14 ghosts of any type at Largo's Overlook, just northeast of base camp.", completion = "Great work, {name}!  We should not hear from the ghosts again anytime soon.", sourceObjectiveStatus = "unverified-source-field" }
quests[27979] = { id = 27979, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Ministry", description = "I got one more assignment for ye.  This one comes straight down from the Overseer himself.  Seems he was pretty shook up once he heard about that \"Archduke\" ye discovered.\n\nHe's asked for us to hunt down three Twilight ministers that work over in Firewatch Ridge, to the west.  Kiyuubi, Letherio, and Finister are their names, and they each carry some sort o' special rock.  Combine all three and bring 'em back here.\n\nListen, when the Overseer gives orders, ye don't ask questions.  Ye just do it.", sourceObjective = "Obtain Kiyuubi's Spherule, Letherio's Spherule, and Finister's Spherule, then combine them into a Twilight Tripetricine.", progress = "Ye got the thing?", completion = "<Hansel weighs the stone in his hands.>\n\nThis thing is strange, {name}.  I don't know what to make of it.  It ain't natural, that's for sure.", sourceObjectiveStatus = "unverified-source-field" }
quests[27980] = { id = 27980, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Spiders Have to Go", description = "Normal-size spiders, I can handle.\n\nGiant glassweb spiders make me uncomfortable, but they're far enough away that I don't worry too much.\n\nBut lava spiders?  <Lolo shudders.>  Lava spiders are SCARY.  They're enormous spiders.  That live in LAVA.\n\nI just got paid for my last week of work, and I'll pay you well to kill those things.  You'll find 'em all over Searing Gorge.", sourceObjective = "Slay 9 Lava Spiders within Searing Gorge.", completion = "There's no way you coulda killed all the spiders in the gorge, but you definitely made a dent.\n\nFine, here's what I promised ya.  Don't spend it all in one place.  Unless it's at Thorium Point.", sourceObjectiveStatus = "unverified-source-field" }
quests[27981] = { id = 27981, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heat That Just Don't Quit", description = "We smith, we smelt, we roast up whatever spider meat we can get.  Bush chicken if we're lucky.  Point is, all o' this work means we need lots and lots of fire.\n\nGood thing we're smack dab in the middle of firetown.\n\nO' course, the best fire comes from the elementals.  You'll find 'em all over Searing Gorge, but always near lava.  Here, take these flasks and use 'em on the elementals.\n\nOh, did I mention the elementals gotta be alive when you gather your sample?", sourceObjective = "Obtain 10 Filled Furnace Flasks. You must use the Furnace Flasks on living elementals within Searing Gorge.", progress = "Oilfist says he's gonna have us makin' firebombs soon.  All the more need for those flasks.", completion = "Yeeeeeeowch!  Don't just go puttin' this stuff into a dwarf's open hand.  This stuff is burnin' up!\n\nNow me hands are gonna get even more swollen...", sourceObjectiveStatus = "unverified-source-field" }
quests[27982] = { id = 27982, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight Collars", description = "Have ye seen the ridiculous necklaces those Twilight's Hammer cultists all wear?  The gems on those things are bigger than Hansel's fist!\n\nA few hamburger-sized jewels like that, and Burninate over there could really push his blacksmithing business to the next level.  Fetch those collars, and he'll make it worth your while.", sourceObjective = "Obtain 20 Twilight Collars.", progress = "A ruby-hilted hammer... it has a nice ring to it.", completion = "Hmm... the gems looked... sparklier from afar.  Up close, they look kind of dingy.\n\nAh well!  A little spit and polish should do the trick, and if not, I can use 'em to practice my disenchanting.", sourceObjectiveStatus = "unverified-source-field" }
quests[27983] = { id = 27983, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lunk's Adventure: Cranky Little Dwarfs", description = "What you doing?  Why you kill?\n\nYou need to get things from dwarfs?  Ah, Lunk understand.  Lunk have a better way.\n\nListen: you go fight dwarf, but do not kill!  Just fight until dwarf get tired.  Then Lunk will help dwarf fall asleep.  Dwarfs probably just cranky because they don't get sleep.\n\nCome on!  Trust Lunk.", sourceObjective = "Weaken 7 Dark Iron Steamsmiths so Lunk can help them fall asleep.", sourceObjectiveStatus = "unverified-source-field" }
quests[27984] = { id = 27984, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lunthistle's Tale", description = "Will you assist me, mortal? Hear my tale.", sourceObjective = "Hear Zamael tell his tale.", progress = "Allow me to finish my story.", completion = "I have accepted my fate here in this cage, but the prayer must be found.", sourceObjectiveStatus = "unverified-source-field" }
quests[27985] = { id = 27985, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prayer to Elune", description = "Will you assist me, mortal?  Will you find the prayer to Elune?\n\nAs I stated, the prayer was etched onto a golden tablet.  I believe they hold it within one of their vile chests, near the entrance to their cave at the bottom of the ridge.\n\nIf you do recover my prayer, don't bring it back to me.  Instead, take the time to read through it.\n\nAbsolution may be asking too much, based on the sins I've committed.  But that won't stop me from holding out hope.You will learn:", sourceObjective = "Find and read the Prayer to Elune.", sourceObjectiveStatus = "unverified-source-field" }
quests[27986] = { id = 27986, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In the Hall of the Mountain-Lord", description = "The Thorium Brotherhood doesn't maintain a militia - just a few guards, and me, and that's it.  If we're to successfully strike against the Dark Irons of the gorge, we're gonna need help.\n\nMountain-Lord Rendan sits atop that tower across the gorge, to our south.  He doesn't consort with Twilight folks or fire elementals, but he hasn't joined the brotherhood either.  Maybe it's time we paid him a visit.  With his help, we might just stand a chance.", sourceObjective = "Speak with Mountain-Lord Rendan at Iron Summit in Searing Gorge.", completion = "And who might you be?\n\nAh, an emissary from the Thorium Brotherhood.  They're looking for my support?  Fine, I might be willin' to help out...\n\n...for a price.", sourceObjectiveStatus = "unverified-source-field" }
quests[27987] = { id = 27987, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cannonball!", description = "Largo and his minions have been stealing our supplies ever since we setup camp here.  It's frustrating to say the least.\n\nWe have heard reports that he is stockpiling cannonballs in the towers overlooking the water up on his overlook.  Can you head up there and try to recover some of them for us?\n\n{name}, don't forget to keep a watch out for horde too.", sourceObjective = "You need to recover 4 Stacks of Cannonballs from Largo's Overlook for Sergeant Gray. You can find Largo's Overlook just northeast of the base camp.", progress = "Did you find the cannonballs?", completion = "Good job on the recovery effort, {name}. These cannonballs should last us a while.", sourceObjectiveStatus = "unverified-source-field" }
quests[27988] = { id = 27988, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plague...Plague Everywhere!", description = "The best part about this plague is that even when it visually fades away, the remaining residue is still quite potent! However, we still have an enormous area to cover before we're done, with plenty of Godfrey's defenses in the way.\n\nIt appears that the spirits that served Baron Silverlaine and Commander Springvale in life now guard them in death, and Godfrey is using them to deter us. Show them all the iron will of the Forsaken!", sourceObjective = "Kill Baron Silverlaine and Commander Springvale.", progress = "A couple bodiless spirits aren't going to best you, are they?", completion = "Cromush has both a thick skull and a fool's brain, and we'll use that to our advantage. By the time anybody finds out about the plague's true potency, it'll be far too late.\n\nThank you for keeping quiet during his tirade. I promise you won't regret it.", sourceObjectiveStatus = "unverified-source-field" }
quests[27989] = { id = 27989, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruumbo Demands Honey", description = "Ruumbo hungers!\n\nThe Deadwood jerks have stolen all their honey from the Timbermaw tribe! We saw...er, Ruumbo saw them do it! Now Ruumbo must have that honey!\n\nTake this... this stick! Yes, this stick. Take this stick and use it to steal the honey from their beehives in Deadwood Village.\n\nRuumbo must have as much honey as possible. This is vital.", sourceObjective = "Collect 10 Deadwood Honey Globs from the hives in Deadwood Village using Ruumbo's Honey Stick.", progress = "Ruumbo can smell whether you have honey or not!", completion = "Honey! Delicious honey!\n\nWell done, ugly creature! You may put the honey...put the honey down right there. No, to the left. Yes, there. Just leave it there.", sourceObjectiveStatus = "unverified-source-field" }
quests[27990] = { id = 27990, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battlezone", description = "It vould appear zhat anozher opportunity has arisen for you to redeem yourself, {race}.\n\nZhis little emergency has set me back a few tank gunnahs.\n\nYou zhink you have vhat it takes to fill in for vone of zhem?\n\nMy tanks are just vest of zhe camp. Get out zhere and put an end to zhis silliness!", sourceObjective = "Commander Schnottz wants you to man one of the siege tank turrets and use it to defeat 7 Decrepit Watchers, then report back to him.", progress = "Vell?\n\nHas our little situation been brought under control?", completion = "Auch!\n\nIf I vere an inch or two taller, I'd be dead!", sourceObjectiveStatus = "unverified-source-field" }
quests[27991] = { id = 27991, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking the Overlook Back", description = "There is only one way for us to take Largo's Overlook back.\n\nI think you know what we need to do {name}.  Largo is pretty paranoid these days so you should be able to find him on top of the tower, looking for his imaginary navy to finally arrive.", sourceObjective = "Sergeant Gray has asked you to kill Commander Largo at Largo's Overlook. The overlook is just northeast of the base camp.", progress = "Were you able to take out Largo?", completion = "Ha, we finally got Largo!  Nice one, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27992] = { id = 27992, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magnets, How Do They Work?", description = "Getting useful machine parts out here on the island has been difficult, {name}.  We have been trying to repair the broken siege engines here in camp but we keep running out of useful parts.\n\nOur second regiment reported some wrecked out siege engines in a old battlefield to the west.  Maybe we could find some parts over there?\n\nYou are going to have trouble finding anything in that old battlefield so take this magnetized scrap collector and put it to some good use.", sourceObjective = "You have been tasked with recovering 7 pieces of Siege Engine Scrap. Use the Magnetized Scrap Collector in The Restless Front to find the scraps. The Restless Front is due west, just past the second bridge.", progress = "Did that magnet contraption actually work?", completion = "These parts will really help us out, {name}!  Who would have thought you can find stuff this useful in all that old junk?", sourceObjectiveStatus = "unverified-source-field" }
quests[27993] = { id = 27993, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Take it to 'Em!", description = "We was lucky to escape, {class}. I'm not sure I'd feel right if we didn't take care of them ambushers.\n\nHows about you git back up to Khartut's tomb and give them little buggers what fer!\n\nIt's off to the northeast, just inside the entrance to Uldum if'n I recollect correctly.\n\nWhat're you looking at? I sure ain't in no condition to do it!", sourceObjective = "Mack wants you to investigate Khartut's Tomb.", completion = "Good to see ya, kid.\n\nWould've been even better if you'd have been here to help me take care of these little savages...", sourceObjectiveStatus = "unverified-source-field" }
quests[27994] = { id = 27994, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruumbo Demands Justice", description = "You! Wanderer! Bow before the might of Ruumbo, great god of the Timbermaw tribe!\n\nHear my will! The evil Deadwood tribe lives in the village behind me! They are big jerks!\n\nI mean, they... they sully my name with their wicked misdeeds! They persecute my cherished Timbermaw tribe and hurt them!\n\nI demand you inflict my justice! Defeat the Deadwood and I will give you my... my favor! Yes! The favor of RUUMBO!", sourceObjective = "Slay 15 Deadwood Furbolg of any type.", progress = "Ruumbo demands you defeat the jerks! I mean, the Deadwood tribe!", completion = "It worked!\n\nI mean, uh, YES, the will of Ruumbo has been carried out! You have done well, creature! You may have these shiny coins!", sourceObjectiveStatus = "unverified-source-field" }
quests[27995] = { id = 27995, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dance for Ruumbo!", description = "You have done well, {race}! Ruumbo is pleased by your bravery, and the delicious honey you have given Ruumbo.\n\nNow, you must... you must dance! Yes!\n\nDance for Ruumbo! Dance!", sourceObjective = "Do a silly dance for Ruumbo.", completion = "Those two brats... I should have known! They were smart enough to hush whenever I went to examine the totem.\n\nI'll be sure to find them and drag them back to Timbermaw Hold by the ears! Thank you for looking into it...", sourceObjectiveStatus = "unverified-source-field" }
quests[27996] = { id = 27996, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orders Are For the Living", description = "Unsurprisingly, we aren't going to listen to Cromush about the plague. However, his brute strength will come in handy for muscling my men through the many foes ahead on the path to Godfrey, the most powerful being his right hand man, Lord Walden.\n\nI'll meet you in Walden's chamber after you finish him off. Then, at long last, we can completely take Shadowfang Keep for the Forsaken!", sourceObjective = "Kill Lord Walden.", progress = "You have your orders, {name}.", completion = "The time has come! Godfrey will fall!", sourceObjectiveStatus = "unverified-source-field" }
quests[27997] = { id = 27997, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Corruption of the Jadefire", description = "The cleansing of this forest has been a grueling process. For every success we have achieved, a new challenge has arisen.\n\nThe Jadefire satyr have been a constant nuisance. They seek to corrupt the forest just as we seek to cleanse it. Now, we have taken steps to begin eradicating them from Felwood entirely.\n\nTravel to Jadefire Glen to the west and rid the forest of their presence. You'll find the entrance just north of the walls of Deadwood Village; look for their vile banners.", sourceObjective = "Slay 12 Jadefire Satyr or Jadefire Felsworn in Jadefire Glen.", completion = "The Emerald Circle thanks you, {name}. If we all work together here, we can purge these demons from our midst.", sourceObjectiveStatus = "unverified-source-field" }
quests[27998] = { id = 27998, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sweet, Merciless Revenge", description = "If all goes well you'll just be able to walk right into Godfrey's personal domain and take a reward fitting for such an eager young {class}.\n\nGodfrey is a cunning foe, though, so it may be wise to head up there quickly just in case you're needed. He will pay for what he did to the Dark Lady!", sourceObjective = "Kill Lord Godfrey.", progress = "Let's get going.", completion = "For a moment there, I thought all was lost. Even when surrounded by the worgen in Gilneas I had higher hopes!\n\nBut you proved me wrong {name}. I will see to it that Sylvanas herself hears of your triumph here today. Don't worry about the mess here, I will gladly see to it myself.", sourceObjectiveStatus = "unverified-source-field" }
quests[27999] = { id = 27999, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fate of the Doyles", description = "It seems the Doyles already joined their last fight. Iain will want to know of their fate.", sourceObjective = "Return the news of Clan Doyle to Iain Firebeard at the Firebeard Cemetery.", completion = "That's a right shame. Stubborn as they were to speak to, they were just as stubborn in a fight. Would have been good to have 'em.\n\nOnce this is done, we'll have to send some boys out to bring them back for a proper send off.", sourceObjectiveStatus = "unverified-source-field" }
quests[28000] = { id = 28000, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Do the Imp-Possible", description = "The satyr hide their corrupted moonwell behind an impenetrable barrier of demonic fire. Their forces must have some way of getting through it.\n\nInterrogating the satyr will be useless, but the imps they consort with will be easily swayed. I have a specific one in mind, as well...\n\nIn the foothills to the east, a lone imp has been seen wandering, far from the other demons. He should prove easy pickings. Weaken him with combat, and then use this enchanted sack to capture him. Then I'll do the talking...", sourceObjective = "Weaken Impsy and use the Enchanted Imp Sack to capture him.", progress = "Do you have an imp for me?", completion = "Imps are creatures of deception. With so many of them spotted at Shadowlurk Ridge, I'm positive something is being hidden there.\n\nOur little friend will tell us exactly how to find it... if he doesn't want to go back in the sack.", sourceObjectiveStatus = "unverified-source-field" }
quests[28001] = { id = 28001, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Coward's Due", description = "We may be safe here, but there are a lot of Wildhammer who could still use support. Our wing can offer that, but we need to keep bolsterin' our forces if we're going to clear the Twilight completely.\n\nI'm going to have words with Colin Thundermar. Only a coward turns down the callin' of his people, especially in a time this dire.\n\nGo to Thundermar, find Colin and get a real explanation out of'm. I won't be putting up with cowardice in a Wildhammer leader.", sourceObjective = "Speak to Colin Thundermar in Thundermar.", completion = "Here here, WOT!? He calls ME a COWARD!?\n\nJust like a Firebeard, all hot air and not a lick of sense. I've been bearing the brunt of a Dragonmaw invasion from the south, much of Thundermar is in ruins, and do any of the other clans stick up to help? NO! Ol' Thundermar is on his own he is, and you'd better believe I'm usin' everything in my arsenal just to stem the tide.", sourceObjectiveStatus = "unverified-source-field" }
quests[28002] = { id = 28002, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crisis Management", description = "There is a delicate situation that calls for the... objective discretion of an outsider.\n\nYou see, an unfortunate incident has upset some of our guests. Rest assured, our top men are sorting out the details.\n\nIn the meantime, it would be wonderful if you could calm our more squeamish visitors.\n\nHandle this well, and the furrier is sure to hear of it!", sourceObjective = "Belloc Brightblade wants you to reassure the guests at Schnottz's Landing.", progress = "Were you able to but the guests' minds at ease, {race}?", completion = "Hmm, still a bit frazzled, are they?\n\nWell, you know what they say. Time heals all wounds.\n\nExcept for those of the ambassador, of course...", sourceObjectiveStatus = "unverified-source-field" }
quests[28003] = { id = 28003, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Ragefire Chasm", description = "The Warchief has requested that any able-bodied adventurer head to Ragefire Chasm, just beneath the great city of Orgrimmar, immediately!\n\nThe Searing Blade is poised to launch an attack at any moment and the city guards cannot hold for much longer! If you so choose, head to Ragefire Chasm and speak with Stone Guard Kurjack, head of the defense initiative, to end the threat to Orgrimmar once and for all.", sourceObjective = "Speak with Stone Guard Kurjack.", sourceObjectiveStatus = "unverified-source-field" }
quests[28004] = { id = 28004, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: The Deadmines", description = "The Warchief has requested that any able-bodied adventurer head to the Deadmines, in the distant land of Westfall, immediately!\n\nAssistance is required in the initiative to take the Defias Juggernaut for the Horde to use against the Alliance! If you so choose, head to the Deadmines and speak with Kagtha, a rogue of the Shattered Hand, to aid in the ongoing war against the Alliance.", sourceObjective = "Speak with Kagtha.", sourceObjectiveStatus = "unverified-source-field" }
quests[28005] = { id = 28005, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: The Deadmines", description = "King Varian Wrynn has requested that any able-bodied adventurer head to the Deadmines, in southern Westfall, immediately!\n\nAssistance is required in stopping the reborn Defias Brotherhood from terrorizing the area! If you so choose, head to the Deadmines and speak with Lieutenant Horatio Laine, lead investigator on the case, to aid in stopping the Defias once and for all.", sourceObjective = "Speak with Lieutenant Horatio Laine.", sourceObjectiveStatus = "unverified-source-field" }
quests[28006] = { id = 28006, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Wailing Caverns", description = "The Warchief has requested that any able-bodied adventurer head to the Wailing Caverns, just west of the Crossroads, immediately!\n\nNaralex must be awakened to save the Barrens! If you so choose, head to the Wailing Caverns and speak with Nalpak, one of Naralex's disciples, to help in healing the injured land.", sourceObjective = "Speak with Nalpak.", sourceObjectiveStatus = "unverified-source-field" }
quests[28007] = { id = 28007, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Wailing Caverns", description = "King Varian Wrynn has requested that any able-bodied adventurer head to the Wailing Caverns, just west of the Crossroads, immediately!\n\nNaralex must be awakened to save the Barrens! If you so choose, head to the Wailing Caverns and speak with Nalpak, one of Naralex's disciples, to help in healing the injured land.", sourceObjective = "Speak with Nalpak.", sourceObjectiveStatus = "unverified-source-field" }
quests[28008] = { id = 28008, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Shadowfang Keep", description = "The Warchief has requested that any able-bodied adventurer head to Shadowfang Keep, in southern Silverpine Forest, immediately!\n\nThe traitor, Lord Godfrey, must pay for what he did to Sylvanas! If you so choose, head to Shadowfang Keep and speak with Deathstalker Commander Belmont, leader of the war effort there, to help enact proper revenge.", sourceObjective = "Speak with Deathstalker Commander Belmont.", sourceObjectiveStatus = "unverified-source-field" }
quests[28009] = { id = 28009, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Shadowfang Keep", description = "King Varian Wrynn has requested that any able-bodied adventurer head to Shadowfang Keep, in southern Silverpine Forest, immediately!\n\nThe traitor, Lord Godfrey, must pay for what he did to our new allies! If you so choose, head to Shadowfang Keep and speak with Packleader Ivar Bloodfang, leader of the war effort there, to help enact proper revenge.", sourceObjective = "Speak with Packleader Ivar Bloodfang.", sourceObjectiveStatus = "unverified-source-field" }
quests[28010] = { id = 28010, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Blackfathom Deeps", description = "The Warchief has requested that any able-bodied adventurer head to Blackfathom Deeps, north of Zoram'gar Outpost, immediately!\n\nThe Twilight's Hammer threatens the world with its actions there! If you so choose, head to Blackfathom Deeps and speak with Je'neu Sancrea, a member of the Earthen Ring, to help stop the Twilight threat.", sourceObjective = "Speak with Je'neu Sancrea.", sourceObjectiveStatus = "unverified-source-field" }
quests[28011] = { id = 28011, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Blackfathom Deeps", description = "King Varian Wrynn has requested that any able-bodied adventurer head to Blackfathom Deeps, west of Astranaar, immediately!\n\nThe Twilight's Hammer threatens the world with its actions there! If you so choose, head to Blackfathom Deeps and speak with Sentinel Aluwyn, head of the night elf effort there, to help stop the Twilight threat.", sourceObjective = "Speak with Sentinel Aluwyn.", sourceObjectiveStatus = "unverified-source-field" }
quests[28012] = { id = 28012, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Stormwind Stockade", description = "King Varian Wrynn has requested that any able-bodied adventurer head to the Stormwind Stockade, inside his highness' own city, immediately!\n\nA mass riot has begun within! If you so choose, head to the Stockade and speak with Rifle Commander Coe, head rifleman of the Stockade guard, to help quell the uprising.", sourceObjective = "Speak with Rifle Commander Coe.", sourceObjectiveStatus = "unverified-source-field" }
quests[28013] = { id = 28013, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Gnomeregan", description = "King Varian Wrynn has requested that any able-bodied adventurer head to Gnomeregan,west of Ironforge, immediately!\n\nThe Gnomes need help reclaiming their city! If you so choose, head to Gnomeregan and speak with Murd Doc, recruiter for the G-Team, to help in the mission.", sourceObjective = "Speak with Murd Doc.", sourceObjectiveStatus = "unverified-source-field" }
quests[28014] = { id = 28014, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Razorfen Kraul", description = "King Varian Wrynn has requested that any able-bodied adventurer head to Razorfen Kraul, in the southernmost part of the Southern Barrens, immediately!\n\nAuld Stonespire needs assistance in stopping the quilboar before they begin to spread further! If you so choose, head to Razorfen Kraul and speak with Auld Stonespire, a wise and respected shaman, to help stop the menace.", sourceObjective = "Speak with Auld Stonespire.", sourceObjectiveStatus = "unverified-source-field" }
quests[28015] = { id = 28015, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Razorfen Kraul", description = "The Warchief has requested that any able-bodied adventurer head to Razorfen Kraul, in the southernmost part of the Southern Barrens, immediately!\n\nAuld Stonespire needs assistance in stopping the quilboar before they begin to spread further! If you so choose, head to Razorfen Kraul and speak with Auld Stonespire, a wise and respected shaman, to help stop the menace.", sourceObjective = "Speak with Auld Stonespire.", sourceObjectiveStatus = "unverified-source-field" }
quests[28016] = { id = 28016, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Scarlet Monastery Graveyard", description = "The Warchief has requested that any able-bodied adventurer head to the Scarlet Monastery Graveyard, northeast of the Undercity, immediately!\n\nDark Ranger Velonara has requested more soldiers to help her begin her assault! If you so choose, head to the Scarlet Monastery Graveyard and speak with Dark Ranger Velonara, a clever fighter indeed, to do your part.", sourceObjective = "Speak with Dark Ranger Velonara.", sourceObjectiveStatus = "unverified-source-field" }
quests[28017] = { id = 28017, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Scarlet Monastery Library", description = "The Warchief has requested that any able-bodied adventurer head to the Scarlet Monastery Library, northeast of the Undercity, immediately!\n\nDark Ranger Velonara has requested more soldiers to help her take out their defenses! If you so choose, head to the Scarlet Monastery Library and speak with Dark Ranger Velonara to do your part.", sourceObjective = "Speak with Dark Ranger Velonara.", sourceObjectiveStatus = "unverified-source-field" }
quests[28018] = { id = 28018, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Scarlet Monastery Armory", description = "The Warchief has requested that any able-bodied adventurer head to the Scarlet Monastery Armory, northeast of the Undercity, immediately!\n\nDark Ranger Velonara has requested more soldiers to help her take out their offensive capabilities! If you so choose, head to the Scarlet Monastery Armory and speak with Dark Ranger Velonara to do your part.", sourceObjective = "Speak with Dark Ranger Velonara.", sourceObjectiveStatus = "unverified-source-field" }
quests[28019] = { id = 28019, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Scarlet Monastery Cathedral", description = "The Warchief has requested that any able-bodied adventurer head to the Scarlet Monastery Cathedral, northeast of the Undercity, immediately!\n\nDark Ranger Velonara has requested more soldiers to help her put the final nail in the Scarlet Crusade's coffin! If you so choose, head to the Scarlet Monastery Cathedral and speak with Dark Ranger Velonara to relish in Forsaken victory!", sourceObjective = "Speak with Dark Ranger Velonara.", sourceObjectiveStatus = "unverified-source-field" }
quests[28020] = { id = 28020, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Scarlet Monastery Graveyard", description = "King Varian Wrynn has requested that any able-bodied adventurer head to the Scarlet Monastery Graveyard, northeast of the Undercity, immediately!\n\nJoseph the Awakened, a former crusader, has requested aid to help him take out the leaders there and reform the crusade! If you so choose, head to the Scarlet Monastery Graveyard and speak with Joseph the Awakened to do your part.", sourceObjective = "Speak with Joseph the Awakened.", sourceObjectiveStatus = "unverified-source-field" }
quests[28021] = { id = 28021, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Scarlet Monastery Library", description = "King Varian Wrynn has requested that any able-bodied adventurer head to the Scarlet Monastery Library, northeast of the Undercity, immediately!\n\nJoseph the Awakened has requested more aid to help him rid the Crusade of their magi! If you so choose, head to the Scarlet Monastery Library and speak with Joseph the Awakened to help bring the crusaders back into the Light.", sourceObjective = "Speak with Joseph the Awakened.", sourceObjectiveStatus = "unverified-source-field" }
quests[28022] = { id = 28022, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Scarlet Monastery Armory", description = "King Varian Wrynn has requested that any able-bodied adventurer head to the Scarlet Monastery Armory, northeast of the Undercity, immediately!\n\nJoseph the Crazed has requested help to kill Herod, the Scarlet Champion! If you so choose, head to the Scarlet Monastery Armory and speak with Joseph the Crazed to help him out.", sourceObjective = "Speak with Joseph the Crazed.", sourceObjectiveStatus = "unverified-source-field" }
quests[28023] = { id = 28023, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Scarlet Monastery", description = "King Varian Wrynn has requested able-bodied adventurers to assault the Scarlet Monastery, northeast of the Undercity, immediately!\n\nRepeated efforts to negotiate with the Scarlet Crusade have failed. Their zealotry is wreaking havoc across the reclaimed plaguelands and elsewhere.\n\nReport to the Scarlet Monastery to dish out the King's justice. Use of deadly force is encouraged!", sourceObjective = "Enter the Scarlet Monastery.", sourceObjectiveStatus = "unverified-source-field" }
quests[28024] = { id = 28024, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Razorfen Downs", description = "King Varian Wrynn has requested that any able-bodied adventurer head to Razorfen Downs, in Thousand Needles, immediately!\n\nThe mysterious Koristrasza needs help to stop the Scourge-Quilboar alliance! If you so choose, head to Razorfen Downs and speak with Koristrasza to lend her your skills.", sourceObjective = "Speak with Koristrasza.", sourceObjectiveStatus = "unverified-source-field" }
quests[28025] = { id = 28025, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Razorfen Downs", description = "The Warchief has requested that any able-bodied adventurer head to Razorfen Downs, in Thousand Needles, immediately!\n\nThe mysterious Koristrasza needs help to stop the Scourge-Quilboar alliance! If you so choose, head to Razorfen Downs and speak with Koristrasza to lend her your skills.", sourceObjective = "Speak with Koristrasza.", sourceObjectiveStatus = "unverified-source-field" }
quests[28026] = { id = 28026, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Uldaman", description = "The Warchief has requested that any able-bodied adventurer head to Uldaman, near New Kargath, immediately!\n\nThe Reliquary and its leader, High Examine Tae'thelan Bloodwatcher, requires assistance in obtaining powerful relics within! If you so choose, head to Uldaman and speak with the High Examiner to aid their cause.", sourceObjective = "Speak with High Examiner Tae'thelan Bloodwatcher.", sourceObjectiveStatus = "unverified-source-field" }
quests[28027] = { id = 28027, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Uldaman", description = "King Varian Wrynn has requested that any able-bodied adventurer head to Uldaman, in the Badlands, immediately!\n\nThe Explorers' League, under Lead Prospector Durdin, requires assistance in braving great danger in pursuit of knowledge! If you so choose, head to Uldaman and speak with Lead Prospector Durdin to help them out.", sourceObjective = "Speak with Lead Prospector Durdin.", sourceObjectiveStatus = "unverified-source-field" }
quests[28028] = { id = 28028, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siege!", description = "That Overseer Oilfist couldn't'a picked a worse time to ask me to join a fight.  My summit's already under siege!\n\nIt's nothin' my guards can't handle, but still, it won't be easy for me to just pick up and send some dwarves into that infernal gorge.\n\nTell ya what: you take out their marksmen that're holding our fortress under siege, and I'll consider your offer.  Ye'll find 'em slinkin' around the flats to the east.", sourceObjective = "Slay 9 Dark Iron Marksmen.", completion = "If nothin' else, you bought us some time, and some room to open up our supply lines through this siege.\n\nYer a fine {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28029] = { id = 28029, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Set Them Ablaze!", description = "I'm not sure if ye've noticed, but my tower's much taller than any o' the other towers here around the Gorge.  Some dwarves pride themselves at how deep they can dig, but not me.  Sometimes I think I shoulda been born a Wildhammer.\n\nI still don't like the sight o' those other towers, though.  Reachin' up like that, ticklin' my tower's feet.  Here, take this torch, an' use it on the braziers atop those other towers.  They'll be sorry they ever built 'em to begin with.", sourceObjective = "Use the Torch of Retribution on the four towers surrounding the Cauldron.", completion = "Looks like ye know how to light things on fire!  An admirable trait in any {race}, for sure.", sourceObjectiveStatus = "unverified-source-field" }
quests[28030] = { id = 28030, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Build a Better Bullet", description = "Those gorge-digging dwarves do at least one thing right: they make very high-quality bullets.  I've been unable to reproduce their results, so I've taken to stealing whatever bullets of theirs that I can find.\n\nYe want my help?  Get me a couple hundred bullets from those marksmen below.\n\nI'm sure they'll be happy to give ye their bullets one at a time, but you might find it faster just to look for the crates filled with them.", sourceObjective = "Obtain 200 Dark Iron Bullets.", progress = "A real {class} woulda caught the bullets with his teeth.", completion = "I'll just divvy these up amongst the guards.  Ye have my thanks.", sourceObjectiveStatus = "unverified-source-field" }
quests[28031] = { id = 28031, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Special Delivery for Brivelthwerp", description = "I have a new business partner, my best buddy, Brivelthwerp. Even as we speak, he's building up the infrastructure for our new ice cream empire!\n\nHe took our coolant tug, inventory, and employees southwest to the Sunken Dig Site. Unfortunately, I don't currently have a way to deliver something to him... something extremely important: our super-secret I-Scream Cryocannon!\n\nYou don't mind taking it to him, do you, {name}?", sourceObjective = "Deliver the I-Scream Cryocannon to Brivelthwerp at the Sunken Dig Site in Thousand Needles.", progress = "That's not what I think it is? Is it?!", completion = "That must be the new I-Scream Cryocannon! Ain't she a beauty?!\n\n<Brivelthwerp eyes you shrewdly.>\n\nI'm going to let you in on a secret, my good friend: the groundwork for a vast mercantile empire is being laid right here!\n\nTell me... how do you feel about ice cream?", sourceObjectiveStatus = "unverified-source-field" }
quests[28032] = { id = 28032, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mysteries of the Fire-Gizzard", description = "There's so much we don't know about the incendosaurs.  Where did they come from?  How do they survive out here on the flats?  And why do they taste so bad?\n\nThe key to understanding these prehistoric beasts, I believe, starts with the fire-gizzard.  Every incendosaur has one.  I'd like a few of them to study.\n\nYou'll find incendosaurs circling the foot of Iron Summit, mostly to the west.", sourceObjective = "Obtain 6 Fire-Gizzards.", progress = "I'm finally getting my hands on those lizard gizzards!", completion = "Ooh, these are nice.  Now, leave me alone with my gizzards.  I've got studying to do!\n\n<Agnes starts to poke the gizzards with a stick.>\n\nYes, very interesting.  Very interesting indeed...", sourceObjectiveStatus = "unverified-source-field" }
quests[28033] = { id = 28033, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deceit", description = "What?  Why're you still here?  Oh, did I promise that I'd help you and the Thorium Brotherhood in yer fight?\n\nI lied.\n\nI just can't spare the men right now.  I know I said I'd help, but there's absolutely no way you can convince me to leave Iron Summit right now.  Absolutely no way.", sourceObjective = "Find a way to convince Mountain-Lord Rendan to join the Thorium Brotherhood.", completion = "Well well well.  Look who come searching for Lunk this time!\n\nThis sounds like case for Lunk's unique brand of no-kill problem-solve.", sourceObjectiveStatus = "unverified-source-field" }
quests[28034] = { id = 28034, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lunk's Adventure: Rendan's Weakness", description = "Lunk not smart, but Lunk notice things.  Today, Lunk notice that Mountain-Dwarf likes to watch people dance.\n\nLunk like to dance!  {name} like to dance!  Probably!\n\nMaybe we find some more dwarfs that like to dance.  Then we go talk to Mountain-Dwarf, and he will listen to {name}.", sourceObjective = "Speak with three Iron Summit Guards and ask them to join your dance.", progress = "I thought I told you that I wasn't interested.  Why are you still here?", completion = "Did I stutter?  I believe I clearly stated that I... won't...\n\nWow, ye've got some good moves there!  I'm impressed!", sourceObjectiveStatus = "unverified-source-field" }
quests[28035] = { id = 28035, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mountain-Lord's Support", description = "Alright, alright!  If I knew ye could dance like that, I wouldn't'a asked ye to do all that stuff earlier.\n\nTell Overseer Oilfist that I'll be joinin' ye.  I'll meet ye in the slag pit, <lad/lass>!  With the combined forces of Thorium Point and Iron Summit, those gorge-dwarves won't know what hit 'em!", sourceObjective = "Report your success to Overseer Oilfist at Thorium Point in Searing Gorge.", completion = "So, Rendan's on our side?  About time that oaf came around.\n\nLet's get moving, then.", sourceObjectiveStatus = "unverified-source-field" }
quests[28036] = { id = 28036, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Zul'farrak", description = "King Varian Wrynn has requested that any able-bodied adventurer head to Zul'farrak, just west of Gadgetzan, immediately!\n\nGadgetzan is being threatened by the Sandfury trolls and their growing army! If you so choose, head to Zul'farrak and speak with Tran'rek to help the goblins out.", sourceObjective = "Speak with Tran'rek.", sourceObjectiveStatus = "unverified-source-field" }
quests[28037] = { id = 28037, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Zul'farrak", description = "The Warchief has requested that any able-bodied adventurer head to Zul'farrak, just west of Gadgetzan, immediately!\n\nGadgetzan is being threatened by the Sandfury trolls and their growing army! If you so choose, head to Zul'farrak and speak with Tran'rek to help the goblins out.", sourceObjective = "Speak with Tran'rek.", sourceObjectiveStatus = "unverified-source-field" }
quests[28038] = { id = 28038, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood in the Highlands", description = "You've got some fight in you, {class}. You might do well in the crucible.\n\nWhat!? You haven't heard of the Crucible of Carnage? That smarmy goblin Gurgthock and his troll sidekick have been plastering us with leaflets ever since he set up shop here in the Highlands. Champions from all over Azeroth fight to the death in there. You should gather up some friends and see how you fare.\n\nThe Crucible is just to the southwest. Look for Wodin the Troll-Servant somewhere in the middle of a ring of bones.", sourceObjective = "Talk to Wodin the Troll-Servant at the Crucible of Carnage in Twilight Highlands.", completion = "Hey, you're one big strong heap of {class}. Can you handle the crucible? We got bookies standing by!", sourceObjectiveStatus = "unverified-source-field" }
quests[28039] = { id = 28039, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Maraudon", description = "The Warchief has requested that any able-bodied adventurer head to Maraudon, in western Desolace, immediately!\n\nHealing Maraudon from its current corruption would great help the entirety of Desolace! If you so choose, head to Maraudon and speak with Zaetar's Spirit, he will guide you.", sourceObjective = "Speak with Zaetar's Spirit.", sourceObjectiveStatus = "unverified-source-field" }
quests[28040] = { id = 28040, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Maraudon", description = "King Varian Wrynn has requested that any able-bodied adventurer head to Maraudon, in western Desolace, immediately!\n\nHealing Maraudon from its current corruption would great help the entirety of Desolace! If you so choose, head to Maraudon and speak with Zaetar's Spirit, he will guide you.", sourceObjective = "Speak with Zaetar's Spirit.", sourceObjectiveStatus = "unverified-source-field" }
quests[28041] = { id = 28041, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bait and Throttle", description = "You can hold your own on the ground, {name}. I'll give you that.\n\nBut we Dragonmaw dominate the skies as well as land. Until you can prove to me you can handle a drake as well as a Dragonmaw, your Horde is nothing to me.\n\nLet's see if you can wrangle one back to Bloodgulch.\n\nFirst you'll need bait. Go out and kill one of the gryphons that wander the woods west or northeast of here. Make sure it's untamed! Drakes hate the stink of dwarf on their food.\n\nGet the gryphon carcass and you'll know what to do.", sourceObjective = "Get a Fresh Gryphon Carcass.", progress = "<You gather up the fresh carcass.>", completion = "<You gather up the fresh carcass.>", sourceObjectiveStatus = "unverified-source-field" }
quests[28042] = { id = 28042, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Special Delivery for Brivelthwerp", description = "I recently came into possession of something that needs to be delivered to a gnome that goes by the name, Brivelthwerp. It's more like Briveltwerp if you ask me.\n\nI want you to take it to him in the southwest, down at the Sunken Dig Site. He's up to something and there's moolah involved... I can smell it!\n\nKeep an eye on what he's doing, {name}, and see if you can't get a cut of his profits. A big cut!", sourceObjective = "Deliver the I-Scream Cryocannon to Brivelthwerp at the Sunken Dig Site in Thousand Needles.", progress = "That's not what I think it is? Is it?!", completion = "<Brivelthwerp eyes you up and down, but becomes overjoyed at the sight of the special delivery.>\n\nWelcome, friend, welcome! I'm going to give you the chance to get involved at the ground level of a once-in-a-lifetime opportuntity.\n\nThe entrepreneurial spirit knows nothing of the differences between the Alliance and the Horde!\n\nTell me... how do you feel about ice cream?", sourceObjectiveStatus = "unverified-source-field" }
quests[28043] = { id = 28043, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "How to Maim Your Dragon", description = "<You sling the gore-spattered gryphon corpse over your shoulder, its wings dragging to the ground.>\n\n<Highland Black Drakes roost just southwest of the Crucible of Carnage, along a ring of low mountain peaks.>\n\n<If you drop the gryphon corpse there, a drake is sure to start feeding. With its guard down, you should be able to attack it until it is weak enough to mount and fly.>", sourceObjective = "Lure in a Baited Black Drake, attack it until it is weak, and then ride it back to Bloodgulch.", completion = "That was an impressive aerial display, {name}, but I wish it had come at a better time.\n\nNarkrall is a great warrior, but he's also an impatient fool. He's about to get himself killed ... and we're about to lose one of our most important weapons in the battle for the Highlands!", sourceObjectiveStatus = "unverified-source-field" }
quests[28044] = { id = 28044, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Touch the Untouchable", description = "I've added a drop of my very own essence to the ooze. Look for a glowing sigil to the west, at the edge of Shadowlurk Ridge. Stand on it, concentrate, and pour this stuff all over yourself. It should be enough to shift you into the nether and let you see what's REALLY there.\n\nYou won't be alone... the satyr's treasure is being guarded by the biggest voidstalker they could summon. Defeat him, and the treasure is yours.\n\nAnd come back in one piece, or this crazy broad's gonna fry me!", sourceObjective = "Use the Phaseblood Potion at the Sigil of Tichondrius to shift into the nether, and search for the Claw of Tichondrius.", progress = "Can you hear me in there, {name}? Do you have the claw?", completion = "The Claw of Tichondrius...\n\nYou hold a piece of the very demon that led the Legion to these woods, {name}. Better for it to be in our hands than with the satyr.\n\nHold still. I'm going to pull you back to our plane and make sure you and the claw arrive here safely...", sourceObjectiveStatus = "unverified-source-field" }
quests[28045] = { id = 28045, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Greatest Flavor in the World!", description = "Below us is a cave. It's huge! The perfect location for our new refrigerated vault. It's big enough to hold all of our inventory with room to grow.\n\nUnfortunately, when we were almost done equipping all of the pipes, bugs burrowed up out of nowhere and killed all of my employees!\n\nHow was I supposed to know?\n\nBut it gave me a great idea: silithid-flavored ice cream. We'll make a killing!\n\nAll I need now are the ingredients.", sourceObjective = "Collect 8 Scoops of Silithid Goo.", progress = "You got enough bug goo for the first batch?", completion = "Oh yeah! This is going to be the greatest flavor in the world!\n\nLook out, Tigule and Foror!!!", sourceObjectiveStatus = "unverified-source-field" }
quests[28046] = { id = 28046, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finish The Job", description = "We have been trying to collect useful scraps from the front all week.  Every time we gather a batch to bring back to camp, we get assaulted by the restless infantry in the area.  Can you head over there and clear them out?", sourceObjective = "Kill 5 Restless Infantry at the Restless Front. You can find the front on the west side of the island, just before Forgotten Hill.", completion = "It's about time someone took those guys out.", sourceObjectiveStatus = "unverified-source-field" }
quests[28047] = { id = 28047, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freezing the Pipes", description = "It's time to break out the I-Scream Cryocannon!\n\nWe lifted the tech from the frost cannons on the river boats. If it's one thing that we gnomes are good at, it's miniaturization by way of making everything else that much bigger!\n\nI need you to take the cannon down there into the cave and freeze the pipes we setup in the walls. That'll jumpstart them.", sourceObjective = "Use the I-Scream Cryocannon to freeze the four pipes inside the cave.", completion = "Do you hear that, {name}? That's the sweet hum of the refrigeration kicking in.\n\nWe'll be able to store our inventory down there in no time. Thank you!", sourceObjectiveStatus = "unverified-source-field" }
quests[28048] = { id = 28048, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "That Smart One's Gotta Go", description = "There's some kind of smart brain bug in the back of the cave. It's in charge of all of the silithid down there.\n\nMy ice cream is melting! How am I supposed to launch my ice cream empire, and save my inventory, if that thing's in there?!", sourceObjective = "Slay the Hive Controller.", completion = "Outstanding! Nothing can stop us from being the greatest purveyors of ice cream in all of Azeroth!", sourceObjectiveStatus = "unverified-source-field" }
quests[28049] = { id = 28049, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "See the Invisible", description = "Yeah, yeah, your stuck-up mage friend there hit it on the nose. The imps over at Shadowlurk Ridge are hiding the key to the satyr's barrier in the nether. It's right there, but you can't see it or touch it unless you're shifted.\n\nI guess you're out of luck though, because only imps can phase shift! So you should just close your eyes, turn around, and let me go...\n\nIt was just a joke! Don't hurt me! I'll need slime from the cursed oozes around these ruins. Bring me enough to cover you from head to toe!", sourceObjective = "Collect 8 batches of Cursed Ooze from the Ruins of Constellas.", progress = "You got that slime?", completion = "Oh good, you're back! Don't leave me alone with her! She's crazy!\n\nGimme that, I'll have you seeing the invisible in no time!", sourceObjectiveStatus = "unverified-source-field" }
quests[28050] = { id = 28050, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shark Tank", description = "I hate sharks.  All of my troops hate sharks too.  This is where you come in, {name}.\n\nI need you to head up to the Cape of Lost Hope and take out a huge shark named Tank.  Tank is not to be trifled with so I would bring a few friends if I were you.", sourceObjective = "You have been tasked to kill Tank, a large shark cruising the waters of the Cape of Lost Hope. The cape can be found north of here, along the northern coastline.", progress = "I don't think you guys have a chance against that shark.", completion = "No way, you actually killed him?  We are having shark tacos tonight for sure!", sourceObjectiveStatus = "unverified-source-field" }
quests[28051] = { id = 28051, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We All Scream for Ice Cream... and then Die!", description = "Don't get me wrong... I'm cheerful on the outside, but inside I'm just terribly torn to pieces. All of my friends and employees are dead.\n\nCould you do me a favor? Would you swim down there and attach the tug's tow hook to my dead employees? I'll reel them in.", sourceObjective = "Attach the tug's tow hook to 10 Dead Employees.", completion = "Thank you, {name}. They gave their lives for ice cream.", sourceObjectiveStatus = "unverified-source-field" }
quests[28052] = { id = 28052, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation: Stir the Cauldron", description = "I'm putting you on a flying machine, {name}.\n\nYou'll be responsible for softening our landing into the slag pit.  Speak with your flight master here in Thorium Point, then fly down to the gorge.\n\nOnce you near your landing point, there will undoubtedly be hordes of Dark Iron dwarves waiting for you.  Use our flying machine's guns to take out as many of them as you can, then land at the cavern's entrance.  Rendan should be waiting for you by the time you arrive.", sourceObjective = "Speak to the Thorium Point flight master, then use the Brotherhood Flying Machine's guns to kill Cauldron Defenders until the area is safe for entry.", completion = "Well, here we are.\n\nI hope you're ready, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28053] = { id = 28053, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lunk Like Your Style", sourceObjective = "Lunk heared that you used the stone to banish fire-lizard.  You saved Gorge, and you didn't even kill!\n\nLunk so proud.  Lunk happy to be {name}'s teacher.\n\nMaybe you take this.  Lunk doesn't need it.  Lunk too busy adventuring!", sourceObjectiveStatus = "unverified-source-field" }
quests[28054] = { id = 28054, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slavery is Bad", description = "Much like Overseer Maltorius, I'm a rich dwarf.  However, I earned my riches through hard work and wise decisions, not through slavery.\n\nOK fine, very little slavery.  Hardly any.\n\nAnyhow, the first thing that I see inside these caverns are slavedrivers and taskmasters.  I won't stand for this!  As you progress through the cavern, kill as many as you can.  Report your results to Evonice Sootsmoker, deeper within the Slag Pit.", sourceObjective = "Slay 10 Dark Iron Taskmasters or Dark Iron Slavers.", completion = "You've done good.  I don't like slavery either.", sourceObjectiveStatus = "unverified-source-field" }
quests[28055] = { id = 28055, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sweet, Horrible Freedom", description = "Of course, we'll want to free as many slaves as we can while we're here.  Most of them will likely join forces with us, anxious to fight against their captors.\n\nHowever, sometimes you will find that slaves are resistant to being freed.  It's a strange phenomenon, often called \"Durnholde Syndrome\".\n\nEither way, you should try to free them.  If they resist, treat them as enemies.  Report your results to Evonice Sootsmoker, deeper within the Slag Pit.", sourceObjective = "Free 12 Slave Workers. If they resist, kill them.", progress = "Let's free a few more of these slaves before we move on.", completion = "Strange how so many slaves cope poorly with freedom.  It's a shame to have to do what we do, but such are the truths of war.\n\nNow, we must move on to more pressing tasks.", sourceObjectiveStatus = "unverified-source-field" }
quests[28056] = { id = 28056, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rise, Obsidion", description = "Overseer Maltorius is in charge here, but he's not the only dwarf of power within the Slag Pit.  Lathoric the Black and his horrifying golem, Obsidion, loom just down this corridor.\n\nInterfering with Lathoric's altar should summon both of them.  Find it, then summon Lathoric and kill him.  Report to Evonice Sootsmoker when you're finished.", sourceObjective = "Use the Altar of Suntara, then slay Lathoric the Black and Obsidion.", completion = "A fight well-fought, {name}!  I'm beginning to feel the tide turn.\n\nNow, when you're ready, let's hit these Dark Irons where it really hurts!", sourceObjectiveStatus = "unverified-source-field" }
quests[28057] = { id = 28057, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kill 'em With Sleep Deprivation", description = "It's a little known fact that dwarves, particularly of the Dark Iron variety, need rest! Lots of rest!\n\nNow I ask you; How can they sleep without pillows?  Exactly, {name}, they can't.  This is why you must steal their pillows.\n\nOnce you've finished your cushion-thievery, talk with Taskmaster Scrange.  He's a bit deeper in the cave, working on a covert project with Hansel.", sourceObjective = "Obtain 16 Dark Iron Pillows.", progress = "What?  Pillows?\n\nWhat?", completion = "I see Evonice is up to her old tricks again.  I guess I'll just... um... hang onto these pillows for a while.\n\nThe important part is that you're here.  We're going to need your help.", sourceObjectiveStatus = "unverified-source-field" }
quests[28058] = { id = 28058, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Look at the Size of It!", description = "Well, well, well... Isn't this a surprise. The Chambermaid had a gigantic ornate pillow and now it's yours. Evonice Sootsmoker will definitely want to get her grubby little hands all over this item. Take it to her and see if she'll offer you any goodies for your trouble.", sourceObjective = "Take Chambermaid Pillaclencher's Pillow to Evonice Sootsmoker in the Searing Gorge.", progress = "That is one huge pillow! Where'd you get it from?", completion = "This is better than even I could have thought possible! The Chambermaid's magical pillow is mine! You better believe you're going to get a nice reward for this accomplishment, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[28059] = { id = 28059, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Claiming The Keep", description = "Have you seen the keep on the north side of the island, {name}?  That is where Keep Lord Farson runs his operation from.\n\nFarson has a small group of dedicated followers and they have been giving us trouble since we got here.  We sent a small group to investigate and they reported back on his exact position within the keep.\n\nCan you finish him off for us?", sourceObjective = "You have been asked to kill Keep Lord Farson at the Farson Hold. Farson Hold can be found on the north side of the island.", completion = "You killed him?  We have been trying to take that guy out for weeks!  We thank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28060] = { id = 28060, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twisted Twilight Ties", description = "Hansel and I came here on a secret mission: kill Overseer Maltorius.  While our main goal still remains the same - defeating Archduke Calcinder - it can't hurt to take out the infamous overseer of the Slag Pit while we're here.\n\nProblem is, Hansel was only prepared to fight one dwarf, but it looks like Maltorius has a visitor... an emissary from the Twilight's Hammer!\n\nSpeak with Hansel and help him out.  Then proceed down this corridor and along the balcony outside to find Overseer Oilfist.", sourceObjective = "Speak with Hansel Heavyhands and help him assault Overseer Maltorius and Twilight-Lord Arkkus.", completion = "Twilight's Hammer, eh?  I should've expected as much.  I'm glad you arrived to help them out when you did.\n\nIt looks like, despite all odds, we've pressed our offensive to the doorstep of Calcinder's lair.  It's now time to finish the job.", sourceObjectiveStatus = "unverified-source-field" }
quests[28061] = { id = 28061, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Minions of Calcinder", description = "There is such a thing as digging too deep, {name}.  While you'll find the richest mineral veins deep below the surface, you'll also find the most evil creatures.\n\nLike fire elementals.\n\nCalcinder's minions roam the cavern ahead.  Every one of them holds a piece of Calcinder's evil within it.  Slay as many as you can, and show no remorse.", sourceObjective = "Slay 6 Searing Flamewraiths.", sourceObjectiveStatus = "unverified-source-field" }
quests[28062] = { id = 28062, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "From Whence He Came", description = "Archduke Calcinder squirms in the back of this very cavern.  We are close to killing him... but that is not what we are going to do.\n\nSlaying Calcinder here means nothing.  His acolytes can easily revive him.  Instead, we are going to banish him.\n\nI asked you to gather a precious stone from the Twilight's Hammer earlier.  You will now use it against Calcinder.  Engage him, weaken him, then use this device on him.  He will be banished from this realm.\n\nGood luck, brave {name}.", sourceObjective = "Weaken Archduke Calcinder, then use the Sanctified Tripetricine to banish him.", sourceObjectiveStatus = "unverified-source-field" }
quests[28063] = { id = 28063, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leave No Weapon Behind", description = "Battle supplies are hard to come by on this rock.  Every time we hold off another horde attack, it feels like we are fighting with sticks and stones.\n\nReports have come in that Keep Lord Farson on the north side of the island has a large stockpile of rifles that we could use.  Can you head down there and check it out?\n\nBe careful {name}, Farson's followers will do anything to protect him.", sourceObjective = "Retrieve 12 Rusty Rifles from Farson Hold on the north side of Tol Barad Peninsula.", progress = "Any luck with those rifles?", completion = "Thanks for rounding these up for us, {name}.  Kind of hard to fight a battle without any guns.", sourceObjectiveStatus = "unverified-source-field" }
quests[28064] = { id = 28064, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome to the Brotherhood", description = "You should return to Thorium Point.  Overseer Oilfist and the rest of the Thorium Brotherhood will be wondering how you fared in the fight against Calcinder.", sourceObjective = "Report to Overseer Oilfist at Thorium Point in Searing Gorge.", completion = "Our task is complete, and it's all thanks to you, {name}.  I'd like to offer you your choice from our coffers.  In addition, I intend to make you a full-fledged member of our order.\n\nWelcome to the Thorium Brotherhood, {name}.  I'm proud to call you a brother.", sourceObjectiveStatus = "unverified-source-field" }
quests[28066] = { id = 28066, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: The Sunken Temple", description = "The Warchief has requested that any able-bodied adventurer head to the Sunken Temple, not far from Stonard, immediately!\n\nThe Atal'ai trolls within are attempting to summon forth Hakkar the Soulflayer! If you so choose, head to the Sunken Temple and speak with the green dragon Lord Itharius, who is prepared to put an end to these dangerous trolls.", sourceObjective = "Speak with Lord Itharius.", sourceObjectiveStatus = "unverified-source-field" }
quests[28067] = { id = 28067, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: The Sunken Temple", description = "King Varian Wrynn has requested that any able-bodied adventurer head to the Sunken Temple, not far from Marshtide Watch, immediately!\n\nThe Atal'ai trolls within are attempting to summon forth Hakkar the Soulflayer! If you so choose, head to the Sunken Temple and speak with the green dragon Lord Itharius, who is prepared to put an end to these dangerous trolls.", sourceObjective = "Speak with Lord Itharius.", sourceObjectiveStatus = "unverified-source-field" }
quests[28068] = { id = 28068, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Blackrock Depths", description = "King Varian Wrynn has requested that any able-bodied adventurer head to Blackrock Depths, northwest of Morgan's Vigil, immediately!\n\nThe Dark Iron dwarves pose a serious threat to the citizens of Redridge! If you so choose, head to Blackrock Depths and speak with Morgan, who has returned from her extended absence and wishes to enact her vengeance on the Dark Iron nation.", sourceObjective = "Speak with Morgan.", completion = "You look eager to kill a few hundred Dark Irons in justice's name.\n\nPerfect.", sourceObjectiveStatus = "unverified-source-field" }
quests[28069] = { id = 28069, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Blackrock Depths", description = "The Warchief has requested that any able-bodied adventurer head to Blackrock Depths, west of Flame Crest, immediately!\n\nThe Dark Iron dwarves have already attacked Alliance-held Redridge, and if left unchecked, may soon threaten our few Horde footholds in southern Azeroth.\n\nIf you so choose, head to Blackrock Depths and speak with High Executioner Nuzrak, who is reforming the Kargath Expeditionary Force to finish off the Dark Irons once and for all.", sourceObjective = "Speak with High Executioner Nuzrak.", completion = "We've managed to take this small area, but to do anything more we'll need your help.", sourceObjectiveStatus = "unverified-source-field" }
quests[28070] = { id = 28070, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Blackrock Spire", description = "The Warchief has requested that any able-bodied adventurer head to Blackrock Spire, west of Flame Crest, immediately!\n\nNefarian's armies and Rend Blackhand's followers threaten the very existence of the Horde! If you so choose, head to Blackrock Spire and speak with Acride, our only contact within that may be able to help us stop the impending invasion.", sourceObjective = "Speak with Acride.", sourceObjectiveStatus = "unverified-source-field" }
quests[28071] = { id = 28071, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Blackrock Spire", description = "King Varian Wrynn has requested that any able-bodied adventurer head to Blackrock Spire, northwest of Morgan's Vigil, immediately!\n\nNefarian's armies and Rend Blackhand's followers threaten the entirety of His Majesty's kingdom! If you so choose, head to Blackrock Spire and speak with Acride, our only contact within that may be able to help us stop the impending invasion.", sourceObjective = "Speak with Acride.", sourceObjectiveStatus = "unverified-source-field" }
quests[28072] = { id = 28072, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Dire Maul Warpwood Quarter", description = "King Varian Wrynn has requested that any able-bodied adventurer head to Dire Maul's Warpwood Quarter, east of Feathermoon Stronghold, immediately!\n\nAlzzin the Wildshaper has corrupted the area and could take over the entire Maul! If you so choose, head to the Warpwood Quarter and speak with Furgus Warpwood, one of the few uncorrupt beings left inside alive.", sourceObjective = "Speak with Furgus Warpwood.", sourceObjectiveStatus = "unverified-source-field" }
quests[28073] = { id = 28073, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Dire Maul Warpwood Quarter", description = "The Warchief has requested that any able-bodied adventurer head to Dire Maul's Warpwood Quarter, west of Camp Mojache, immediately!\n\nAlzzin the Wildshaper has corrupted the area and could take over the entire Maul! If you so choose, head to the Warpwood Quarter and speak with Furgus Warpwood, one of the few uncorrupt beings left inside alive.", sourceObjective = "Speak with Furgus Warpwood.", sourceObjectiveStatus = "unverified-source-field" }
quests[28074] = { id = 28074, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Dire Maul Capital Gardens", description = "The Warchief has requested that any able-bodied adventurer head to Dire Maul's Capital Gardens, west of Camp Mojache, immediately!\n\nThe fallen Highborne Prince Tortheldrin is using the massive demon Immol'thar to control the area! If you so choose, head to the Capital Gardens and speak with Estulan, a recently discovered pure Highborne seeking to reclaim the fallen city for his people.", sourceObjective = "Speak with Estulan.", sourceObjectiveStatus = "unverified-source-field" }
quests[28075] = { id = 28075, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Dire Maul Capital Gardens", description = "King Varian Wrynn has requested that any able-bodied adventurer head to Dire Maul's Capital Gardens, east of Feathermoon Stronghold, immediately!\n\nThe fallen Highborne Prince Tortheldrin is using the massive demon Immol'thar to control the area! If you so choose, head to the Capital Gardens and speak with Estulan, a recently discovered pure Highborne seeking to reclaim the fallen city for his people.", sourceObjective = "Speak with Estulan.", sourceObjectiveStatus = "unverified-source-field" }
quests[28076] = { id = 28076, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Northern Dire Maul", description = "King Varian Wrynn has requested that any able-bodied adventurer head to Northern Dire Maul, east of Feathermoon Stronghold, immediately!\n\nKing Gordok and his growing army of Gordok ogres pose the largest and most powerful threat in the area to us! If you so choose, head to Northern Dire Maul and speak with the Druid of the Talon already sent there as a forward scout.", sourceObjective = "Speak with the Druid of the Talon.", sourceObjectiveStatus = "unverified-source-field" }
quests[28077] = { id = 28077, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Northern Dire Maul", description = "The Warchief has requested that any able-bodied adventurer head to Northern Dire Maul, west of Camp Mojache, immediately!\n\nKing Gordok and his growing army of Gordok ogres pose the largest and most powerful threat in the area to us! If you so choose, head to Northern Dire Maul and speak with the Stonemaul Ogre already sent there as a forward scout.", sourceObjective = "Speak with the Stonemaul Ogre.", sourceObjectiveStatus = "unverified-source-field" }
quests[28078] = { id = 28078, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Stratholme Main Gate", description = "The Warchief has requested that any able-bodied adventurer head to Stratholme's main gate, due north from Plaguewood, immediately!\n\nThe Dreadlord Balnazzar has slain the Scarlet Crusade and resurrected them as the Risen! If you so choose, head to the main gate and speak with Crusade Commander Eligor Dawnbringer, leader of the Argent Crusade effort to retake Stratholme for its true owners.", sourceObjective = "Speak with Crusade Commander Eligor Dawnbringer.", sourceObjectiveStatus = "unverified-source-field" }
quests[28079] = { id = 28079, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Stratholme Main Gate", description = "King Varian Wrynn has requested that any able-bodied adventurer head to Stratholme's main gate, due north from Plaguewood, immediately!\n\nThe Dreadlord Balnazzar has slain the Scarlet Crusade and resurrected them as the Risen! If you so choose, head to the main gate and speak with Crusade Commander Eligor Dawnbringer, leader of the Argent Crusade effort to retake Stratholme for its true owners.", sourceObjective = "Speak with Crusade Commander Eligor Dawnbringer.", sourceObjectiveStatus = "unverified-source-field" }
quests[28080] = { id = 28080, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Stratholme Service Gate", description = "King Varian Wrynn has requested that any able-bodied adventurer head to Stratholme's service gate, just northwest of the Northpass Tower, immediately!\n\nLord Aurius Rivendare, former paladin of the Silver Hand and recently resurrected son of none other than Baron Rivendare himself, now leads the remaining scourge forces there! If you so choose, head to the service gate and speak with Crusade Commander Eligor Dawnbringer, leader of the Argent Crusade effort to retake Stratholme for its true owners.", sourceObjective = "Speak with Crusade Commander Eligor Dawnbringer.", sourceObjectiveStatus = "unverified-source-field" }
quests[28081] = { id = 28081, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Stratholme Service Gate", description = "The Warchief has requested that any able-bodied adventurer head to Stratholme's service gate, just northwest of the Northpass Tower, immediately!\n\nLord Aurius Rivendare, former paladin of the Silver Hand and recently resurrected son of none other than Baron Rivendare himself, now leads the remaining scourge forces there! If you so choose, head to the service gate and speak with Crusade Commander Eligor Dawnbringer, leader of the Argent Crusade effort to retake Stratholme for its true owners.", sourceObjective = "Speak with Crusade Commander Eligor Dawnbringer.", sourceObjectiveStatus = "unverified-source-field" }
quests[28082] = { id = 28082, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Scholomance", description = "King Varian Wrynn has requested that any able-bodied adventurer head to Scholomance, east of Andorhal, immediately!\n\nRecent necromantic activity in the area points to Darkmaster Gandling, and a renewed effort to train powerful sorcerers for the scourge. If you so choose, travel to Scholomance to cleanse this bastion of evil from the Plaguelands.", sourceObjective = "Enter Scholomance.", sourceObjectiveStatus = "unverified-source-field" }
quests[28083] = { id = 28083, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Scholomance", description = "The Warchief has requested that any able-bodied adventurer head to Scholomance, east of Andorhal, immediately!\n\nRas Frostwhisper and Darkmaster Gandling are still hard at work training powerful sorcerers for the scourge! If you so choose, head to Scholomance and speak with Alexi Barov, one of the last heirs to the Barov fortune and our contact within the dark school.", sourceObjective = "Speak with Alexi Barov.", sourceObjectiveStatus = "unverified-source-field" }
quests[28084] = { id = 28084, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Might of the Krom'gar", sourceObjective = "You may now make use of the Krom'gar stockpile, {name}! For a small fee I will sell you armaments of battle, useful for crushing your enemies! The availability of what I sell depends upon your rank in the army. Visit my shop whenever you earn a new rank.\n\nLOK'TAR OGAR!", sourceObjectiveStatus = "unverified-source-field" }
quests[28085] = { id = 28085, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trouble at Highperch", description = "Thank you for your help, {name}. You should speak with Pao'ka Swiftmountain at Highperch to the southwest.\n\nPerhaps he will know the whereabouts of the Elder Crone?", sourceObjective = "Speak with Pao'ka Swiftmountain at Highperch in Thousand Needles.", completion = "I know nothing of the Elder Crone, Magatha. What I do know is that the Twilight's Hammer is destroying Highperch.\n\nWill you help me to stop them, {class}?", sourceObjectiveStatus = "unverified-source-field" }
quests[28086] = { id = 28086, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Free the Pridelings", description = "The trappers are rounding up all of the young wind riders. {name}, will you go out there and free the pridelings?", sourceObjective = "Free 12 Highperch Pridelings.", completion = "They're precious. One day they'll grow strong, but until then, they must be protected.", sourceObjectiveStatus = "unverified-source-field" }
quests[28087] = { id = 28087, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death to all Trappers!", description = "There's only one answer for those filthy Twilight's Hammer trappers! Death!\n\nBring me their nets, {name}.", sourceObjective = "Collect 8 Trapper Nets.", progress = "What insanity could drive someone to do such horrible things?", completion = "There'll be no more trapping this day!", sourceObjectiveStatus = "unverified-source-field" }
quests[28088] = { id = 28088, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Release Heartrazor", description = "The Twilight's Hammer have the alpha male of Highperch pinned down. You must head east up the ramp and release Heartrazor before the pride loses its patriarch!", sourceObjective = "Release Heartrazor from all bonds restraining him.", completion = "The great Heartrazor is a majestic creature. He has told me of his gratitude and fondness for you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28089] = { id = 28089, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Hillsbrad Foothills!", description = "All able bodied members of the Horde are hereby ordered to report to High Executor Darthalia at Southpoint Gate in Hillsbrad Foothills. The Forsaken war machine marches ever onward, securing Lordaeron for the Horde!\n\nTo reach Southpoint Gate you must follow the road south through Silverpine Forest and take the east fork leading into Hillsbrad Foothills.\n\nOnward, <brother/sister>! Destiny calls!", sourceObjective = "Report to High Executor Darthalia at Southpoint Gate in Hillsbrad Foothills.", completion = "I was wondering when reinforcements would show up. Suit up, {name}. It's time to dispense some justice!", sourceObjectiveStatus = "unverified-source-field" }
quests[28090] = { id = 28090, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Precious Goods", description = "The gates further down the canyon are shut. Our scouting revealed some kind of stone that they carry in chests in their caravans that they use to open the gates.\n\nGet down there and look for a chest key on the bodies of the guards. When you find it, use it on one of those chests on the caravan wagons and bring the gatestone back to me.", sourceObjective = "Retrieve a Twilight Caravan Gatestone. The Spearwardens should carry keys that can get you into the gatestone chests.", progress = "You know, we could probably just blow the gates, but knowing our demoman, we're probably better off dodging the risk.", completion = "Good going.\n\nDoesn't look like much, does it?", sourceObjectiveStatus = "unverified-source-field" }
quests[28091] = { id = 28091, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Easy Pickings", description = "The ambush launched smoothly. Most of the guards are dead, but a few are still pinned down with the wagons.\n\nYou can see them just to our west, in the canyon below. Get in there and clear them out so we can get this attack on the move.", sourceObjective = "Kill 8 Twilight Spearwarders.", completion = "Excellent. Now we can start pushing our ground forces up towards Grim Batol.", sourceObjectiveStatus = "unverified-source-field" }
quests[28092] = { id = 28092, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "If The Key Fits", description = "The wyrms have already taken the battle to the sky above Grim Batol. It's up to us to move our men in by ground and secure the gates.\n\nI want you to know what is at stake here, {class}. Grim Batol is the source of Twilight's Hammer reinforcements to all of the highlands. If we do not cut them off here, we will not win the battles ahead.\n\nI'm sending the Gob Squad with you. Get to the gate to the southeast and get it open. Patch should have any further instructions you'll need from there.", sourceObjective = "Lead the Gob Squad to the closed Dragonmaw Gate.\n\nIf you lose the Gob Squad, return to Warlord Krogg for reassignment.", progress = "Keep moving. We need to get that gate open.", completion = "Works like a charm, every time.", sourceObjectiveStatus = "unverified-source-field" }
quests[28093] = { id = 28093, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pressing Forward", description = "Good work so far. We should find the entrance to Grim Batol just past the next gate.\n\nI was ordered to secure the entrance and block off reinforcements while the rest of our men press through the path we've cleared up the canyon. I'm thinking if we get there soon enough, maybe I can let Ticker have a little more fun.\n\nLet's get moving down the canyon to the southwest - we should find the next gate pretty quickly.", sourceObjective = "Bring the Gob Squad past the northern Dragonmaw Gate to the entrance of Grim Batol.\n\nIf you are separated from the Gob Squad, return to Warlord Krogg in Wyrms' Bend to be reassigned.", progress = "Welcome, {race}.", completion = "The gate is clear. Once your people finish clearing the canyon, we will speak to your leaders about the next move.", sourceObjectiveStatus = "unverified-source-field" }
quests[28094] = { id = 28094, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paving the Way", description = "My orders are to accompany you south through the Dragonmaw Gates towards the entrance of Grim Batol. We're to clear a path so that the rest of the men can follow us up and secure the entrance.\n\nTranslation: kill everything that moves, and don't be ashamed if you have a good time doing it.\n\nThe boys are getting antsy. Let's go.", sourceObjective = "Kill 30 Twilight's Hammer cultists along Wyrm's Bend as you fight towards the entrance to Grim Batol.", progress = "Not done yet, bucko.", completion = "We make it look easy.", sourceObjectiveStatus = "unverified-source-field" }
quests[28096] = { id = 28096, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome to the Machine", description = "Come in here dear <boy/girl>, have a cigar. You're gonna go far and fly high as a ranking officer of the Forsaken. Yes, indeed, this is the good life and you are going to live it!\n\nI want you to take these orders and dispense them to the lowly scrubs that come along looking for work. Who you give what to is wholly at your discretion.\n\nWhen you're ready, mount up on my trusty skeletal steed - so they don't miss you - and start living the life! Which means just stand there and wait.", sourceObjective = "Hand out 3 Quests.", progress = "How's the \"desk job\" coming?", completion = "So how was it? Everything that you dreamed it would be? Exciting, no?\n\nNo?\n\n<Darthalia sighs.>\n\nI can see that you're a true hero. You need action. I guess a \"desk job\" isn't for you.", sourceObjectiveStatus = "unverified-source-field" }
quests[28097] = { id = 28097, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gates of Grim Batol", description = "Kroggs started the assault to push up the canyon. He's just past the gate to our southeast.\n\nI'm going to get the squad together to join the attack. We'll meet you down there.", sourceObjective = "Speak to Warlord Krogg in Wyrms' Bend.", completion = "The canyon is well fortified, but the distraction that the dragons are providing should be enough to allow us to break through.", sourceObjectiveStatus = "unverified-source-field" }
quests[28098] = { id = 28098, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Twilight Skymaster", description = "Twilight Skymaster Richtofen is at the Twilight Aerie up above and to the southeast. No matter what we do down here, if he's not dealt with, all hope is lost for Highperch.\n\nWhile Heartrazor is too injured to help you with the fight, he can fly you up there. The rest is up to you, {name}.\n\nGood luck.", sourceObjective = "Get a flight from Heartrazor to the Twilight Aerie and deal with Twilight Skymaster Richtofen.", progress = "{name}, you must take care of Twilight Skymaster Richtofen!", completion = "The pridelings did what? They must love you deeply for freeing them.\n\nThank you, {name}. You've saved Highperch!", sourceObjectiveStatus = "unverified-source-field" }
quests[28099] = { id = 28099, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rasha'krak", description = "Based on this information you've delivered, I believe that one of this \"Archduke's\" minions may already have turned its eyes toward Thorium Point.\n\nHis name is Rasha'krak, and he patrols the lava pools just to our south.  He looks like the latent fire elementals that rage nearby, except for one small difference: the bracers of binding that encircle his wrists.\n\nFind him and bring these bracers to me, {name}.  I need proof that we are in danger before we involve ourselves in elemental wars.", sourceObjective = "Obtain Rasha'krak's Bracers of Binding.", progress = "I won't fight any elementals until we have proven that they pose a threat to us.", completion = "It is, unfortunately, as I expected.  These bracers bear the indelible mark of the firelord and his minions.\n\nVery well.  With no Horde or Alliance forces anywhere near this godforsaken gorge, it falls upon the Thorium Brotherhood to stop this Archduke before he spreads any more of his evil.", sourceObjectiveStatus = "unverified-source-field" }
quests[28100] = { id = 28100, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Talking Totem", description = "The furbolg village to the south is the home of the Deadwood tribe, sworn enemies of the Timbermaw. They are corrupted and foul like so many others, driven mad by the taint of these woods.\n\nSomething unusual has occured near the village though. Travelers coming here have said that the totem next to the road has spoken to them.\n\nI have heard nothing every time I approach it. Perhaps it will speak to you, {name}? Maybe you can find out what's going on for me.", sourceObjective = "Speak with the Totem of Ruumbo near Deadwood Village.", completion = "You... yes, you! I have chosen you, {race}, as my champion! You will do the work of Ruumbo!", sourceObjectiveStatus = "unverified-source-field" }
quests[28101] = { id = 28101, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mathias' Command", description = "Recent events make it even more apparent that holing up here and making sporadic attacks on Grim Batol isn't enough to keep our kind safe, much less retake Grim Batol. We need to be more aggressive, we need to strike into their heart.\n\nI've agreed to send dragons to the aid of your commanders. They were already hatching a plan to strike at Grim Batol, so you should focus your attention there first.\n\nYou should be able to find Mathias Shaw in Dragonmaw Pass, in the canyon below us to the south.", sourceObjective = "Speak to Master Mathias Shaw in Dragonmaw Pass.", completion = "The red dragons have agreed to help! No small feat, I'm sure. You have the thanks of the Alliance.\n\nWe'd already laid out plans for our ambush on a Twilight caravan by the time the dragons contacted us. They're helping by cutting off their retreat.\n\nThe battle still rages. You can definitely be of aid.", sourceObjectiveStatus = "unverified-source-field" }
quests[28102] = { id = 28102, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fight the Power", description = "It's time for the final push against the Jadefire!\n\nIf you're prepared to break through their foul barrier and bring the fight to their leader, I'd also ask your help against the lesser satyr. Our druids fight ferociously, but your strength can help turn the battle.\n\nShow the Jadefire that their power will no longer hold sway over these lands!", sourceObjective = "Slay 8 Jadefire Rogues or Jadefire Shadowstalkers at the Ruins of Constellas.", completion = "A few of the remaining satyr have fled into the deeper woods, but they have taken heavy losses. Good job, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28103] = { id = 28103, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Easy Pickings", description = "The ambush launched smoothly. Most of the guards are dead, but a few are still pinned down with the wagons.\n\nGet in there and clear them out so we can push forward into the canyons.", sourceObjective = "Kill 8 Twilight Spearwardens.", completion = "Excellent. Now we can start pushing our ground forces up towards Grim Batol.", sourceObjectiveStatus = "unverified-source-field" }
quests[28104] = { id = 28104, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Precious Goods", description = "The gates further down the canyon are shut. Our scouting revealed a stone that they carried in chests in their caravans that they used to open the gates.\n\nGet down there and look for a chest key on the bodies of the guards. When you find it, use it on one of those chests on the caravan wagons and bring the gatestone back to me.", sourceObjective = "Retrieve a Twilight Caravan Gatestone. The Spearwardens should carry keys that can get you into the gatestone chests.", progress = "They've grown overconfident. More and more, that seems the downfall of the most powerful armies.", completion = "Good going.\n\nDoesn't look like much, does it?", sourceObjectiveStatus = "unverified-source-field" }
quests[28105] = { id = 28105, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kavem the Callous", description = "Kavem was cruel enough before the Neferset signed up with Deathwing.  His pleasure in deriving pain now borders on the insane.\n\nIt is he who now holds the keys to our shackles.\n\nHe dwells in the building next to us, to my right.\n\nFind him and take the key from him.  Do not hesitate or show him mercy.  He will slit your throat and think nothing of it.", sourceObjective = "Obtain the Neferset Key from Kavem the Callous.", progress = "You're back.  Do you have the key?", completion = "Excellent, {name}.  We will make our way out of here soon enough.", sourceObjectiveStatus = "unverified-source-field" }
quests[28106] = { id = 28106, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gates of Grim Batol (DO NOT DELETE, DO NOT DEPRECATE!)" }
quests[28107] = { id = 28107, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paving the Way", description = "My orders are to accompany you south through the Dragonmaw Gates towards the entrance of Grim Batol. We're to clear a path so that the rest of the men can follow us up and secure the entrance.\n\nTranslation: kill everything that moves, and don't be ashamed if you have a good time doing it.\n\nThe boys are getting antsy. Let's go.", sourceObjective = "Kill 30 Twilight's Hammer cultists along Wyrm's Bend as you fight towards the entrance to Grim Batol.", progress = "We're not finished yet.", completion = "We make it look easy.", sourceObjectiveStatus = "unverified-source-field" }
quests[28108] = { id = 28108, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "If The Key Fits", description = "The wyrms have already taken the battle to the sky above Grim Batol. It's up to us to move our men in by ground and secure the gates.\n\nI want you to know what is at stake here, {class}. Grim Batol is the source of Twilight's Hammer reinforcements to all of the highlands. If we do not cut them off here, we will not win the battles ahead.\n\nI'm sending a squad from Highbank with you. Get to the gate to the southeast and get it open. Your lieutenant should have any further instructions you'll need from there.", sourceObjective = "Lead squad from Highbank to the closed Dragonmaw Gate.\n\nIf you lose your squad, return to Master Mathias Shaw for reassignment.", progress = "Keep moving. We need to get that gate open.", completion = "Like a well-oiled machine.", sourceObjectiveStatus = "unverified-source-field" }
quests[28109] = { id = 28109, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pressing Forward", description = "Good work so far.\n\nWe should find the entrance to Grim Batol just past the next gate. I was ordered to secure the entrance and block off reinforcements while the rest of our men press through the path we've cleared up the canyon.\n\nLet's get moving down the canyon to the southwest - we should find the next gate pretty quickly.", sourceObjective = "Bring your squad past the northern Dragonmaw Gate to the entrance of Grim Batol.\n\nIf you are separated from your squad, return to Master Mathias Shaw in Wyrms' Bend to be reassigned.", progress = "Welcome, {race}.", completion = "The gate is clear. Once your people finish clearing the canyon, we will speak to your leaders about the next move.", sourceObjectiveStatus = "unverified-source-field" }
quests[28111] = { id = 28111, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trouble at Azurelode", description = "Productivity from our spider farm at the Azurelode Mine is at a standstill. Captain Keyton has requested that we send help immediately. Keyton claims that the mine spiders refuse command and are running rampant. Furthermore, a group of coastal murlocs are raiding our supplies. I want you to go down there and check things out. Help out Keyton and the spider-handler, {name}.\n\nYou'll find Azurelode Mine to the southeast, near the coast.", sourceObjective = "Report to Captain Keyton at the Azurelode Mine in Hillsbrad Foothills.", completion = "We're in a bit of a bind, {class}. Sarus' spiders are starting to get a little uppity as we've been unable to feed them for days. If we leave the murlocs will overtake our post! Furthermore, Warden Stillwater over at the Sludge Fields is demanding that we send him more humans! He is insatiable! We need help!", sourceObjectiveStatus = "unverified-source-field" }
quests[28112] = { id = 28112, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Escape From the Lost City", description = "Everything is ready!  Undo my chains and set your friends free.\n\nWe must move quickly before the Neferset scum realize we're up to something!\n\nIf we make it, see my brother, King Phaoris for a reward.", sourceObjective = "Free Prince Nadun and speak to King Phaoris at Ramkahen in Uldum.", completion = "It is true then?  An outsider rescued Prince Nadun from the Neferset?\n\nWe are truly in your debt, stranger.", sourceObjectiveStatus = "unverified-source-field" }
quests[28113] = { id = 28113, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Break the Unbreakable", description = "With the claw, we are ready to break through the Jadefire's defenses.\n\nHead into the ruins to the northwest. Beyond the frontline of the satyr you'll find a narrow pass heading to their corrupted moonwell. An enormous wall of demonic flame bars the path, but the Claw of Tichondrius should be able to dispel it.\n\nBeyond the barrier you will find the leader of these forces, Xavathras, guarding the corrupted moonwell. Slay him once you are through!", sourceObjective = "Slay Xavathras.", progress = "Has Xavathras fallen?", completion = "See what can get done with a little cooperation?\n\nI'll make sure the claw is given to people responsible enough to contain such things... assuming it can't be destroyed.", sourceObjectiveStatus = "unverified-source-field" }
quests[28114] = { id = 28114, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glorious Harvest", description = "Directly southeast of Southpoint Gate you will find our spider domestication operations. Through the years we have grown a kinship with the spiders of Hillsbrad and have managed to domesticate and breed the adorable little critters. Spiders now serve us as regular household pets and beasts of battle! Such diverse creatures they are!\n\nI need you to head into the fields to the southeast and carefully harvest the eggs that we have incubating on the bears. Deliver the harvest to Sarus at the mine.", sourceObjective = "Recover 60 Creeper Eggs.", progress = "Have you brought my harvest?", completion = "Wonderful! Now to place these eggs into a nice, dark alcove inside the mine and let the miracle of life happen!", sourceObjectiveStatus = "unverified-source-field" }
quests[28115] = { id = 28115, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Past Their Prime", description = "Bears are soulless beasts put upon this earth to torment us. Only through Forsaken ingenuity have we devised a way to make use of the bears so that they may serve some purpose! We use the bears at our spider farm as living egg feeders. Our spiders lay their eggs in the bear flesh and the eggs thrive off of the meat and blood of the beasts.\n\nAfter they have served their purpose the monsters must be put down. Travel southeast and kill the infested bears that have lived past their prime.", sourceObjective = "Kill 8 Infested Bears.", completion = "The bear gods are cruel masters. They will continue to populate this world with bears until the end of days. It is our right as civilized people to make use of this nuisance - for the betterment of us all!", sourceObjectiveStatus = "unverified-source-field" }
quests[28116] = { id = 28116, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crying Violet", description = "We must prepare carefully before assaulting Jaedenar. The magic of the warlocks and demons within Jaedenar is strong, and we will need wards of our own before entering.\n\nWe need only one more ingredient: Crying Violet, which grows in the hills near the enemy's stronghold to the northwest. \n\nGather the Crying Violet, then meet my assistant in the field. He will know what to do next.", sourceObjective = "Collect 8 Crying Violets.", progress = "Have you found the crying violet yet, {name}? We need them quickly.", completion = "Wonderful. Greta chose wisely when she asked you to perform this task. I will work the herbs immediately...", sourceObjectiveStatus = "unverified-source-field" }
quests[28117] = { id = 28117, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clearing the Depths", description = "You are a sight for sore eyes, {name}.  Now that we have claimed Tol Barad, the battle has just begun.\n\nWe discovered a cell block just east of here that we need you to clear out.  Turns out that its chock full of ghosts that have been locked up down there for who knows how long.\n\nClear out as much as you can and report back to me when you are done.", sourceObjective = "You have been asked to kill 9 ghosts of any type in the Cursed Depths, just east of Baradin Hold.", completion = "You made it back out alive?  You are a stronger man than I, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28118] = { id = 28118, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Imprisoned Archmage", description = "We have been trying to clear out the Cursed Depths cellblock since we landed on Tol Barad.  It seems that everytime we get close, that archmage shows up and pushes us back.\n\nNow that we have claimed the island, it's time we take another shot.  Head down there and bring me back his staff as proof that you have finished the job.", sourceObjective = "You must kill Archmage Galus and return with his Staff from the Cursed Depths, just east of Baradin Hold.", progress = "Have you been able to take out the Archmage?", completion = "Galus is dead?  Fantastic work {name}, now we can send down the cleanup crew and get that cellblock ready for new prisoners.", sourceObjectiveStatus = "unverified-source-field" }
quests[28119] = { id = 28119, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Purity From Corruption", description = "The flowers you brought me were the essential ingredient.\n\nProtective barriers surround Shadow Hold, projected from demonic braziers. If we are to drive the Shadow Council from Felwood, then those braziers must be extinguished.\n\nThis vial has been infused with crying violet and the magic of the wilds. Fill it at the corrupted moonwell in the center of Jaedenar and return to me.", sourceObjective = "Fill the Empty Canteen with water from the corrupted moonwell in the center of Jaedenar.", progress = "Do you have the waters from the corrupted moonwell?", completion = "This will do nicely, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28120] = { id = 28120, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learning From The Past", description = "Now that we finally have a hold on this wretched island, we can start to investigate how it got in this condition.  Some of our troops have discovered journals around the entrance to the Cursed Depths cellblock just east of here.\n\nThese journals are of particular interest to our elder scribes back at base camp.  I need you to recover four of them and bring them back to me as fast as you can.\n\n{name}, be careful down there, that place is crawling with undead.", sourceObjective = "You have been asked to recover four Dusty Prison Journals from the Cursed Depths, just east of Baradin Hold.", progress = "Were you able to recover the journals?  Reports mentioned that they were sighted both in and out of the cells down there.", completion = "These journals are in excellent condition {name}.  We will begin deciphering them immediately.  Only time will tell what secrets they hold.", sourceObjectiveStatus = "unverified-source-field" }
quests[28121] = { id = 28121, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forces of Jaedenar", description = "The Shadow Council perpetuates the corruption of this land. At Jaedenar in the northwest, they worship the demons of the Burning Legion, and work to open the path for their masters to return to this world.\n\nThe grounds are patrolled by Jaedenar Hounds, Guardians, Adepts, and Cultists - thugs that act as lookout for the more vile forces beneath. They will be the first to die so that these forests may no longer suffer!", sourceObjective = "Slay 12 Jaedenar Forces.", completion = "Good, {name}! With their numbers weakened, we can soon begin our assault on their forces deep within Shadow Hold.", sourceObjectiveStatus = "unverified-source-field" }
quests[28122] = { id = 28122, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Huge Problem", description = "We finally capture this godforsaken rock and then we find out that there is a huge ettin roaming around, taking out our sentry patrols!\n\n{name}, I need you to round up a few friends and take that ettin down.  We can't have a beast like that roaming around, wreaking havoc.\n\nStay alert, reports from the front say that he is carrying a huge tree as a weapon, and he is not afraid to use it.", sourceObjective = "You have been asked to kill Problim, a giant ettin that roams the paths of Tol Barad.", completion = "You actually killed him?!  I can't believe it!", sourceObjectiveStatus = "unverified-source-field" }
quests[28123] = { id = 28123, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Demon Chain", description = "Narkrall revealed to me the secret of his influence over the drakes in this area. I thought the Demon Chain was a myth, but he's had it all along.\n\nAnd now the fool is about to lose it!\n\nHis life is meaningless to me but the Dragonmaw can't afford to lose that artifact. Follow him north, up to Thundermar. The city will be in chaos, so you may be able to land undetected. Return to me with the Demon Chain, even if you have to remove it from Narkrall's corpse.\n\nFind that artifact, {name}!", sourceObjective = "Acquire the Demon Chain.", progress = "Do you have it? Yes? The fate of the Dragonmaw depends on the Demon Chain!", completion = "<Zaela takes the gore-spattered length of chain and wraps it around her hand and wrist.>\n\nIf the stories are true, {name}, it was on this length of chain that Deathwing had once fastened the Demon Soul, forged in his bid to control the other dragonflights. The Demon Soul has long been destroyed but perhaps this hunk of elementium holds some residual power...\n\nYou've done a great thing today.", sourceObjectiveStatus = "unverified-source-field" }
quests[28124] = { id = 28124, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On to the Bulwark", description = "{name}, while you and the pridelings were taking care of the skymaster, Lakota Windsong came by. She told me to tell you to meet her east at the Twilight Bulwark.\n\nThat must be where they're holding Magatha Grimtotem.", sourceObjective = "Speak with Lakota Windsong at the Twilight Bulwark in Thousand Needles.", completion = "I'm glad that you made it.\n\nDon't mind my new clothes. It seemed prudent to blend in.", sourceObjectiveStatus = "unverified-source-field" }
quests[28125] = { id = 28125, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Something to Wear", description = "I've got an idea for how you can get close to their leaders without getting killed. But first, you're going to need to find something to wear.\n\nMy suggestion is that you head up there and get their armor from them.", sourceObjective = "Collect 10 pieces of Twilight's Hammer Armor.", progress = "How much of that armor have you collected?\n\nYou're going to want to be well disguised for the next thing that you're going to have to do.", completion = "<Lakota looks worried about the condition of the armor, especially the bloodstains.>\n\nYou sure don't fool around, do you, {name}? Well, it'll have to do.", sourceObjectiveStatus = "unverified-source-field" }
quests[28126] = { id = 28126, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dousing the Flames of Protection", description = "The braziers are spread throughout Shadow Hold.\n\nEnter the tunnel into Shadow Hold, and follow it through the underground passageways. Douse each of the brazier's flames and the protections the Council has set up will fall for at least a short period of time.", sourceObjective = "Use the Purified Moonwell Water to douse the four Braziers of Protection within Shadow Hold.", completion = "With the braziers gone, the druids of the Emerald Circle can enter Shadow Hold and clear out the last of the cultists. In time, it may even be used as the barrow den it once was.\n\nYou have my thanks, {name}. Please take this reward.", sourceObjectiveStatus = "unverified-source-field" }
quests[28127] = { id = 28127, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Break Them Out", description = "Magatha's not the only one that the Twilight's Hammer have taken prisoner.\n\nWhile you're up there to the south, you should break as many of them out as you can.", sourceObjective = "Rescue 5 Bulwark Prisoners from the Twilight Jailers.", completion = "You give so much of yourself without requiring anything in return.\n\nThe people of Thousand Needles are grateful, as am I.", sourceObjectiveStatus = "unverified-source-field" }
quests[28128] = { id = 28128, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Inner Circle", description = "With their outer sentries gone, the greater members of the Shadow Council are next.\n\nDeep within the corrupted barrow dens you'll find powerful Jaedenar Warlocks, Hunters, Enforcers, Darkweavers, and Legionnaires.\n\nThey must be defeated if these lands are to be saved!", sourceObjective = "Slay 12 defenders inside Shadow Hold.", completion = "The cleansing of Shadow Hold will take much time and effort, but without your defeat of the Shadow Council, it would not be possible at all. Thank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28129] = { id = 28129, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Demon Prince", description = "The Jadefire satyr that have overrun so much of Felwood work directly with the Shadow Council.\n\nThese satyr answer directly to the ancient and powerful Prince Xavalis. Some say he is the son of Xavius, the first satyr, blessed by Sargeras himself.\n\nWhatever his nature, he must die if we are to scatter the Jadefire and reclaim our barrow dens. Journey deep into Shadow Hold and slay him. Show him no mercy; he will have none for you.", sourceObjective = "Slay Prince Xavalis.", completion = "The demons begin to fall! Take heed, {class}. You will find even stronger foes deeper within Shadow Hold.", sourceObjectiveStatus = "unverified-source-field" }
quests[28130] = { id = 28130, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not The Friendliest Town", description = "Have you been up to Rustberg Village yet {name}?  I would suggest you bring a sharpened blade if you are heading that direction.\n\nThe folks in that town look alright but something suspicious is going on in there.  Reports have been coming in that they are picking off our soldiers left and right.  We have had just about enough of that, so I need you to head down there and do a little cleaning house for us.\n\nTake down as many as you can and report back when you are done.", sourceObjective = "Commander Marcus Johnson has asked you to kill 14 villagers in Rustberg Village. Rustberg Village is just north of base camp, on the right side.", completion = "Told you that village was full of wackos.  Nice job clearing it out {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28131] = { id = 28131, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twin Temptresses", description = "Moora and Salia are the personal servants of Shadow Lord Fel'dan. Do not be deceived by them!\n\nThese foul succubi use their wiles and foul magic to draw mortals deep into Shadow Hold. Those in their grasp undergo brainwashing, or are sacrificed by Fel'dan to his demonic masters.\n\nThe two fight as one and are never found apart, making them a considerable threat. Proceed further into Shadow Hold and slay them.", sourceObjective = "Slay Moora and Salia.", progress = "Rest a while before continuing, {class}.", completion = "Another demonic menace gone. It is time to find their master.", sourceObjectiveStatus = "unverified-source-field" }
quests[28132] = { id = 28132, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Efficient Excavations", description = "This manual describes outlandish theories on how to most efficiently manage large groups of workers as they engage in massive excavation projects.\n\nAfter a quick skim of the material, it becomes clear to you that the author of the book is the figure in charge of the over-aggressive pillagers here.\n\nA map on the back cover indicates that the author has a bunker in the southwest region of Uldum.\n\nPerhaps an introduction is in order.", sourceObjective = "Bring 'Efficient Excavations' to Belloc Brightblade in Schnottz's Landing.\n\nProvided item:", completion = "Oh look, it's one of little Schnottz's pamphlets.\n\nI'll just be taking that from you, if you don't mind.", sourceObjectiveStatus = "unverified-source-field" }
quests[28133] = { id = 28133, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fury Unbound", description = "Narkrall's drake Torth survived the failed attack on Thundermar, and now the creature is free from his former master.\n\nTorth seeks vengeance against the Dragonmaw, and has already strafed Bloodgulch once. He will keep returning until we skewer him for good. It is time to put the Demon Chain to work.\n\nTorth's old nest is a small cave in the hills west of here that we have turned into a small camp called \"The Gullet.\"\n\nMeet me at the Gullet and we will finish Torth off.", sourceObjective = "Travel to the Gullet and speak with Zaela. Kill Torth.", progress = "Our dominance over the dragons is both our strength and our curse. Their wrath is a terrible thing to behold.", completion = "Once free of the chain, Torth died rather than submit again. I admire the creature. I will have his hide fashioned into a set of armor.\n\nThis much is clear to me now: The Dragonmaw cannot stand alone if the Alliance backs the Wildhammer. Narkrall proved that. And you have proven the might of the Horde, again and again.\n\nI will rebuild our drake wings and take up position outside the Bastion of Twilight. You should continue to help out here in the Gullet and elsewhere in the Highlands.", sourceObjectiveStatus = "unverified-source-field" }
quests[28134] = { id = 28134, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Impending Retribution", description = "Now that you've been suitably rewarded, I hope I can speak with you frankly.\n\nYou've done my kingdom a great favor, but you've also unbalanced a fragile peace process.\n\nI was pursuing my brother's release strictly through diplomatic means in order to avoid bloodshed.\n\nNow, the enemy is sure to seek retaliation.\n\nSpeak to Nomarch Teneth at the Tahret Grounds to the east, Sun Priest Asaris at the Seal of the Sun King to the north and Asaq at Mar'at to the west.  Find out where the enemy will strike.", sourceObjective = "Speak to Nomarch Teneth at the Tahret Grounds, Sun Priest Asaris at the Seal of the Sun King, and Asaq at Mar'at.", progress = "You've returned, {name}.  Have you completed the task I request of you?", completion = "Orsis!  Of course!\n\nHow could I not have seen this?", sourceObjectiveStatus = "unverified-source-field" }
quests[28135] = { id = 28135, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Al'Akir's Vengeance", description = "Listen, {name}.  What struck Orsis was no natural sandstorm.  It was the minions of Al'Akir.\n\nThe elemental lord of air is firmly allied with Deathwing and it was only a matter of time before he set his subjects upon my people.\n\nOrsis has been attacked as a warning to us.  We must move quickly to offer our brethren what aid we can.\n\nMeet with Nadun at the Arsad Trade Post outside of Mar'at.  I will begin preparations to take care of the displaced and wounded.", sourceObjective = "Speak to Prince Nadun at the Arsad Trade Post outside Mar'at in Uldum.", completion = "Do you see what Deathwing's minions have done?  Great Orsis is now all but buried in the sand!", sourceObjectiveStatus = "unverified-source-field" }
quests[28136] = { id = 28136, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Behind You!", description = "The three leaders of the Bulwark are powerful and not to be underestimated, {name}. Fortunately for us, you now have a disguise to make you look like one of the Twilight cultists.\n\nYou should put the disguise on and speak with Codemaster Deethuk, Commander Fastfuse, and Elementalist Starion each alone. Get them to turn their backs on you, and when they do, strike quickly!", sourceObjective = "Assassinate Codemaster Deethuk, Commander Fastfuse, and Elementalist Starion.", completion = "Now that those three are dealt with, the combined forces from Freewind Post should be able to handle the rest of the cultists here.", sourceObjectiveStatus = "unverified-source-field" }
quests[28137] = { id = 28137, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teach A Man To Fish.... Or Steal", description = "Rustberg Village.  That place is a curse and a blessing for us, {name}.  I have no clue where bandits learned to fish as well as they do but I have no time to worry about that now.\n\nI need you to head down there and steal as many of their fish reserves as possible.  We have been living off scraps since we retook the island and this is our best chance at some solid food reserves.\n\nKeep an eye out for stealthers up there, reports have told us they are prevalent inside the village walls.", sourceObjective = "You must steal 22 Rustberg Seabass from Rustberg Village. The fish can be found on string stands at the docks, round back of the village. Rustberg Village is due north of base camp, on the right side.", progress = "Were you able to pull off the heist and get us some fish?", completion = "These fish will do nicely, {name}.  Keeping the troops fed and in good condition is our number one priority and you really came through for us here.", sourceObjectiveStatus = "unverified-source-field" }
quests[28138] = { id = 28138, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Human Infestation", description = "This mine was once the heart of Alliance mining operations in Hillsbrad. It now serves as a breeding ground for our loyal spiders, though, the humans still occupy it - in a way.\n\n<Keyton grins.>\n\nBut onto business! Warden Stillwater has called for more workers at the Sludge Fields. I want you to enter the mine with these shackles and capture Hillsbrad humans for labor in the fields.\n\nBreak them out of their web paralysis and beat them into submission before you use the shackles.", sourceObjective = "Capture 8 Hillsbrad Humans.", progress = "We mustn't keep the warden waiting!", completion = "These will do nicely. I do wonder what the warden has planned for them. Last I heard the Sludge Fields were overrun by some very bad things.", sourceObjectiveStatus = "unverified-source-field" }
quests[28139] = { id = 28139, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Codemaster's Code", description = "{name}, the bonds holding Magatha are specially encoded. She can only be released if we get those codes.\n\nThere's a device near Codemaster Deethuk in the Bulwark to the southeast. It contains the codes.\n\nPlease obtain them.", sourceObjective = "Obtain the Codemaster's Code.", progress = "Do you have the codes to the Elder Crone's bonds?", completion = "Good. Now there's only one thing left to do.", sourceObjectiveStatus = "unverified-source-field" }
quests[28140] = { id = 28140, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Elder Crone", description = "You have the code. Now all you have to do is head to the eastern section of the Bulwark and free the Elder Crone.\n\nGood luck, {name}. Thank you for all you've done.", sourceObjective = "Disable Magatha's Bonds Controller.", sourceObjectiveStatus = "unverified-source-field" }
quests[28141] = { id = 28141, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relics of the Sun King", description = "The Seal of the Sun King serves as a defense mechanism for Ramkahen.\n\nWhen the barrier around Uldum fell, we began to see Wastewander outriders from Tanaris filter into our borders.\n\nThey attacked this holy site on their way west and robbed it of the relics which once provided its power.\n\nRecover the relics for us.  Without them we are powerless to defend against attacks from the desert.", sourceObjective = "Obtain 4 Relics of the Sun King.", progress = "Did you succeed?", completion = "Thank you.  The rumors I'd heard about you are proving true after all.", sourceObjectiveStatus = "unverified-source-field" }
quests[28142] = { id = 28142, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Withering", description = "According to Magatha, she'll meet you just outside of the Twilight Withering to the east.", sourceObjective = "Speak with Magatha Grimtotem at the Twilight Withering in Thousand Needles.", completion = "It took you long enough. Do you think that we are playing games here?", sourceObjectiveStatus = "unverified-source-field" }
quests[28143] = { id = 28143, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Withering", description = "You should not keep the Elder Crone waiting, {name}.\n\nShe said that she'd be up top and just outside of the Twilight Withering to the east.", sourceObjective = "Speak with Magatha Grimtotem at the Twilight Withering in Thousand Needles.", sourceObjectiveStatus = "unverified-source-field" }
quests[28144] = { id = 28144, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thieving Little Monsters!", description = "The long stretch of coastline directly south of our position that extends from west to east is known as the Western Strand. Along the Western Strand you will find two things: murlocs and our stolen \"supplies.\"\n\n<Keyton puts his hands in the air and makes quotation marks with his fingers.>\n\nThose damned thieving murlocs struck while our backs were turned and took our \"supplies.\"\n\nSarus and I cannot leave this post. We need you to head to the Western Strand and recover those \"supplies!\"", sourceObjective = "Recover 6 Forsaken Camp \"Supplies.\"", progress = "Recover our \"supplies,\" {name}!", completion = "At least we'll be prepared for any future incidents. Moving \"supplies\" like this around is a risky proposition. You never know who is going to open their big fat mouth.\n\n<Keyton raises what appears to be an eyebrow at you.>", sourceObjectiveStatus = "unverified-source-field" }
quests[28145] = { id = 28145, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Venomblood Antidote", description = "Iset attempted to defend this holy ground when the Wastewander bandits ransacked it.\n\nThey appear to have used the potent toxin present in the venomblood scorpids.\n\nTake this vial and collect venom from their corpses so that I may concoct an antidote.  I fear Iset might not have much time.", sourceObjective = "Fill the Antidote Vial with the poison of 8 Venomblood Scorpid corpses.", progress = "Did you obtain it, {name}?", completion = "Thank you, {name}.  We might yet save Iset.", sourceObjectiveStatus = "unverified-source-field" }
quests[28146] = { id = 28146, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Coastal Delicacies!", description = "My spiders are hungry and agitated! They haven't eaten for days and are starting to sample our human captives. We can't have that. We need those humans for use in the Sludge Fields.\n\nI want you to take one of my hungry mine spiders out and feed it murlocs from the Western Strand, south of here. Whatever you kill, it'll eat! The more the better!", sourceObjective = "Feed the Hungry Mine Spider 12 Murlocs from the Western Strand.", completion = "This should keep it happy and content for a few days. You've done a good thing here, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[28147] = { id = 28147, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Purple is Your Color", description = "So far as I can tell, the Glopgut Ogres right outside the cave here have not yet joined up with the Twilight's Hammer. If we're clever, we can turn the two groups against each other.\n\nLet's roll with a little trick I learned in Silithus. First we'll need to put together a set of cultist robes for you.\n\nHead south of here and kill some Twilight Windwarpers in the Twilight Breach. Aside from disrupting whatever they're up to, it'll give you a chance to collect garment scraps.", sourceObjective = "Gather up 8 Twilight Garment Scraps.", progress = "This is good, {name}. With heroes like you stirring up trouble out here, we'll keep the cult distracted from our main invasion.\n\nDo you have a disguise?", completion = "What did you manage to get? I suppose we can piece something together from this.\n\nAfter all, you're not joining the cult. We just need to fool a few ogres.", sourceObjectiveStatus = "unverified-source-field" }
quests[28148] = { id = 28148, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Culling the Corrupted", description = "The sickening corruption of demons pervades this entire forest. The soil, the trees, the animals... all grow thick with fel magics.\n\nWe of the Emerald Circle have sworn to cleanse this forest, and doing so requires a constant battle. While some life here can still be healed, the bears and wolves that wander nearby have been twisted too far.\n\nWe must end their suffering, and ensure their bodies do not spread the taint further. Hunt the bears and wolves, and return to me with their hides.", sourceObjective = "Collect 10 Corrupted Pelts from Angerclaw Bears or Felpaw Wolves.", progress = "I must have the pelts to purge them of the leftover demon essence.", completion = "I will see these are burned swiftly and safely, {name}. You have my thanks.", sourceObjectiveStatus = "unverified-source-field" }
quests[28149] = { id = 28149, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whispers in the Wind", description = "You hear dem, {class}? De voices from de cave. Dey want to talk, but dey ain't got no breath.\n\nLet's find a way to listen. De Twilight's Hammer, dey talk to de wind. Go to de Twilight Breach south of here, and grab de Windspeaker Charm from de camp. It'll be atop a stone pillar.\n\nWe'll need us de breath of the elementals, too! Slay de Storm Vortexes and take what joo need.", sourceObjective = "Collect a Windspeaker charm and 5 Breath of the Vortex.", progress = "Shhh, {name}! Listen. Listen...", completion = "Dat's de stuff, mon!\n\nNow can you hear dem? De spirits, dey be talkin', but dey say nothing nice.\n\nLet us bring dem to de light.", sourceObjectiveStatus = "unverified-source-field" }
quests[28150] = { id = 28150, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Arcane Ally", description = "The Emerald Circle is sworn to accept the help of any who wish to fight the demons of Felwood. Though my people have long shunned the arcane, we cannot afford to deny ourselves such advantage here.\n\nArcanist Delaris, a surviving Highborne mage, helps us battle the Jadefire satyr. Follow the road to the north, and you will find her at our encampment overlooking the Ruins of Constellas.\n\nIf you wish to help cleanse Felwood, follow her requests as you have mine.", sourceObjective = "Speak with Arcanist Delaris at the Ruins of Constellas.", completion = "There is little time for talk, {class}. The druids fight valiantly against the satyr, but fel sorcery blocks their path.\n\nLuckily, I have a plan...", sourceObjectiveStatus = "unverified-source-field" }
quests[28151] = { id = 28151, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dressed to Kill", description = "Your disguise is ready, {name}. Whenever you go north into Glopgut's Hollow now, your Twilight's Hammer regalia will fool the ogres.\n\nThe rest of the plan is simple: you kill a bunch of Glopgut ogres, and they blame the cult. Are you ready to create some havoc in the ogre camp? I thought so.", sourceObjective = "Kill 10 Glopgut Ogres. Your Twilight's Hammer disguise will automatically apply while inside Glopgut's Hollow.", completion = "Hah! I'm sure Twilight's Hammer wanted to number those ogres among their ranks. Now they'll probably have to fight them off instead.\n\nThis is good, {name}. With one well-placed {class} we managed to do the work of a small army. I'll let Warlord Krogg know of your work here!", sourceObjectiveStatus = "unverified-source-field" }
quests[28152] = { id = 28152, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jaedenar Awaits", description = "The cultists you saw guarding the claw were members of the Shadow Council, foul warlocks behind nearly every attempt to bring demons into Azeroth.\n\nNorth of here is Jaedenar, named in worship of Kil'Jaeden himself. Deep beneath it stretches Shadow Hold, a former barrow den and the Shadow Council's own stronghold on Azeroth.\n\nTake these herbs north to Wildheart Point, on the east side of the road. Greta Mosshoof will need them for her plan to purify Shadow Hold for good.", sourceObjective = "Deliver the Arcanist's Herbs to Greta Mosshoof at Wildheart Point.", progress = "Greetings, {class}. What brings you here?", completion = "Ah, just what I was expecting. With these herbs, our preparations for Jaedenar are nearly ready.", sourceObjectiveStatus = "unverified-source-field" }
quests[28153] = { id = 28153, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadow Lord Fel'dan", description = "Shadow Lord Fel'dan awaits further in the depths, {name}.\n\nHis wrath will be unmatched now that you have slain his beloved pets. Even without Moora and Salia at his side, he is a terrible force to be reckoned with.\n\nBeware his dark powers; he is nearly more demon than orc by now.", sourceObjective = "Slay Shadow Lord Fel'dan.", completion = "The Shadow Council is broken! One task remains...", sourceObjectiveStatus = "unverified-source-field" }
quests[28154] = { id = 28154, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muckgill's Flipper or Something...", description = "This looks like Muckgill's flipper or something. Maybe there's somebody that cares that you killed this murloc back at the Azurelode Mine camp. Probably not, but it's worth a shot.\n\nTake Muckgill's fin or whatever it might be back to Captain Keyton at the Azurelode Mine in southwestern Hillsbrad.", sourceObjective = "Deliver Muckgill's Flipper back to Captain Keyton at the Azurelode Mine in Hillsbrad Foothills.", progress = "Do I look like some kind of murloc scientist?", completion = "Muckgill you say? Never heard of him. What is this anyway? Some kind of fin or something?", sourceObjectiveStatus = "unverified-source-field" }
quests[28155] = { id = 28155, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lord Banehollow", description = "Only one final power remains lurking in the depths of Shadow Hold now: Lord Banehollow.\n\nThe Shadow Council here serves his whims, and even Fel'dan was a mere instrument for him to prepare this land for another invasion of the Burning Legion.\n\nProceed carefully, {name}. A dreadlord is a terrifying foe. Stand tall and triumph!", sourceObjective = "Slay Lord Banehollow.", completion = "Truly incredible, {name}. To journey within the very lair of evil here and slay every fiend that stands before you... I am overwhelmed.\n\nThe Emerald Circle thanks you for your work here in Felwood. As for Andalar, we will send scouts to rescue him at once. He shall have a hero's welcome.", sourceObjectiveStatus = "unverified-source-field" }
quests[28156] = { id = 28156, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deep Mine Rescue", description = "<You can hear Dumass speaking through the webbing.>\n\nHI! SPIDERS EVERYWHERE! THE CAPTAIN SENT ME TO SAVE THE WORLD AND CAPTURE HUMANS! WHAT IS THIS PLACE ANYWAY? IT'S SO HOT! I...\n\n<Dumass goes on and on about his situation.>\n\nPerhaps you should cut him free and get him back to safety. Or you can just leave him here, though it's your fault that he's stuck in this mine.", sourceObjective = "Escort Dumass to Safety!", progress = "Do I look like some kind of baby sitter?", completion = "Have you ever heard the saying \"survival of the fittest?\" What you're doing conflicts with natural law, buddy! This idiot should have died in the mines. There's no telling what kind of harm he'll cause to himself or another person now that you've saved him from his inevitable demise.\n\nAnd you know who's fault that'll be, right?", sourceObjectiveStatus = "unverified-source-field" }
quests[28157] = { id = 28157, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Four Twilight Elements", description = "The Twilight's Hammer have summoned a monstrosity. It's a combination of the four elements infused with the power of their special ore, Elementium.\n\nIf you want to save your precious Thousand Needles from total destruction, you're going to have to destroy it. But first, you'll need a few things to get through its protective shielding.\n\nGo east into the Withering and bring back the four Twilight elements.", sourceObjective = "Collect the four Twilight Elements: Air, Earth, Fire, and Water.", progress = "Do you have all of the elements, {class}?", completion = "<Magatha gazes at you with naked disdain.>\n\nI'll combine them into a suitable form. I'll keep its use simple.", sourceObjectiveStatus = "unverified-source-field" }
quests[28158] = { id = 28158, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unbound", description = "There are two very powerful elementals that the Twilight's Hammer have bound. They are using the bound Fury and Vortex to infuse Animus with a great deal of power.\n\nWhen Animus has absorbed enough of their power, he will explode. The rest of Thousand Needles and much of the surrounding lands, will be obliterated.", sourceObjective = "Unbind the Bound Fury and the Bound Vortex.", completion = "A simple task for a simple boy. Let us see if you have what it takes to finish the job.", sourceObjectiveStatus = "unverified-source-field" }
quests[28159] = { id = 28159, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Doomstone", description = "At the core of Animus is an artifact known as the Doomstone. One of its properties is an ability to absorb a great deal of energy.\n\nThis is how the cultists are trying to set off the explosion... by overloading the stone and amplifying the power through the elemental.\n\nBring me the Doomstone. For safe keeping, of course.", sourceObjective = "Collect the Doomstone.", progress = "Do you have the Doomstone, {class}?", completion = "Surprising... you lived.\n\nI thank you for doing my dirty work, {class}. You kept my hands clean while ridding me of some incompetent Grimtotem leaders.\n\nNot only do I have the Rattle of Bones, the Writ of History, and the Drums of War, but I now have the ultimate artifact: the Doomstone!", sourceObjectiveStatus = "unverified-source-field" }
quests[28160] = { id = 28160, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spread the Word", description = "For rendering me faithful service, I grant you your life. Take it and be gone from my sight. Let your people know of all that has transpired.\n\nAnd {name}, if we ever cross paths again, you will die.", sourceObjective = "Speak with Fizzle Brassbolts on Fizzle & Pozzik's Speedbarge in Thousand Needles.", completion = "Wow, she's evil! But, what does it mean, {name}? Is Magatha going to destroy us? Is she in charge of the Twilight's Hammer now?\n\nWhatever happens, you've delivered us from our enemies. Please allow me to show you our gratitude.", sourceObjectiveStatus = "unverified-source-field" }
quests[28161] = { id = 28161, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spread the Word", description = "For rendering me faithful service, I grant you your life. Take it and be gone from my sight. Let your people know of all that has transpired.\n\nAnd {name}, if ever we cross paths again, you will die.", sourceObjective = "Speak with Pozzik on Fizzle & Pozzik's Speedbarge in Thousand Needles.", completion = "Wow, she's evil! But, what does it mean, {name}? Is Magatha going to destroy us? Is she in charge of the Twilight's Hammer now?\n\nWhatever happens, you've delivered us from our enemies. Please allow me to show you our gratitude.", sourceObjectiveStatus = "unverified-source-field" }
quests[28162] = { id = 28162, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Swamp Bait", description = "Supplies are never easy to find in a place like this, {class}.  We have been scouting since we captured the island but things are not looking good.\n\nFortunately, we just  received a scouting report that a swamp full of crocs is just west of our base camp here.  The hides off those crocs will come in handy for our leatherworkers.  Bring back as many as you can.", sourceObjective = "You have been tasked with collecting 8 Crocolisk Hides from the Baradin Crocolisks on Tol Barad. The crocolisks can be found in the swamp, just west of Baradin Hold.", progress = "You cleared out that swamp yet?", completion = "Looks like you were able to get the croc hides that we needed.  Thanks {name}, your contributions will not go unnoticed.", sourceObjectiveStatus = "unverified-source-field" }
quests[28163] = { id = 28163, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Leftovers", description = "We fought hard to capture this island, {race}.  We cleared out most of the horde scum but I can still smell their foul stench in the air.\n\nI need you to investigate the slagworks, warden's vigil and the ironclad garrison.  Kill any horde that you find.\n\nYou know what they say, the only good horde is a dead horde!", sourceObjective = "You have been instructed to kill 12 Horde Infantry on Tol Barad. You can find the holdouts in The Slagworks, Warden's Vigil and the Ironclad Garrison, here on Tol Barad.", completion = "Those filthy horde never stood a chance.  Nice work, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28164] = { id = 28164, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seek Brother Silverhallow", description = "I just received word that you are needed in Orgrimmar, {name}. Brother Silverhallow has asked for you to return to the city as quickly as you are able. His message didn't include any other information, and the matter seemed urgent.\n\nLook for Brother Silverhallow in the Goblin Slums of Orgrimmar.", sourceObjective = "Speak with Brother Silverhallow in the Goblin Slums of Orgrimmar.", completion = "I'm glad to see you received my message.", sourceObjectiveStatus = "unverified-source-field" }
quests[28165] = { id = 28165, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "D-Block", description = "Have you heard of the D-Block yet {name}?  It's one of the old cellblocks here on the island.  Problem is, it's infested with demons.  We planned on using it to lock up the leftover Horde we found on the island, but that is not going to happen in its current state.\n\nI need you to head down there and clear those demons out.  Report back to me when you are done.", sourceObjective = "You have been instructed to kill 10 demons of any type in the D-Block, just northwest of Baradin Hold.", completion = "D-Block is all clear?  Good work, {name}.  We will send down a crew to start cleaning up right away.", sourceObjectiveStatus = "unverified-source-field" }
quests[28166] = { id = 28166, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thog's Nightlight", description = "To see de spirits, we need a special light. A light that lights up one's insides. De light of souls.\n\nTwilight's Hammer uses dem to root out traitors after what we did to dem in Hyjal. Dey just gave one to de Glopgut ogres as a gift.\n\nInside de Glopgut Hollow to de north, you'll find de great big brute Thog. He's got him a Light of Souls. At least, he will until you take it from him.", sourceObjective = "Get the Light of Souls from Glopgut's Hollow.", progress = "De light of souls. Does you have it, mon?", completion = "Ah, dis be it, mon.\n\n<The lens glows brightly in Buunu's hands, casting unearthly rays of light across the shadowy cave mouth.>\n\nWe be ready to bring dem spirits out de shadows now.", sourceObjectiveStatus = "unverified-source-field" }
quests[28167] = { id = 28167, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Carvo Blastbolt", description = "I'm going to start preparing my men to leave this place. We can't hold out here any longer. I want you to move to a forward position in the middle of the large room ahead.\n\nYou should find Carvo Blastbolt there. He'll give you further instructions. Good luck, {name}, and I'll see you on the surface.", sourceObjective = "Report to Carvo Blastbolt in Gnomeregan.", completion = "Did Nevin send you ahead? That means he's getting ready to end the mission, but there are still survivors to be rescued. We have to help them!", sourceObjectiveStatus = "unverified-source-field" }
